DG.put("krisnaavtaar/46",{"n":46,"title":null,"title_roman":null,"page":485,"blocks":[{"type":"heading","kind":"speaker","name":"ਗੋਪਿਨ ਬਾਚ ਆਪਸ ਮੈ","gurmukhi":"ਗੋਪਿਨ ਬਾਚ ਆਪਸ ਮੈ","roman":"Gopin baach aapas mai","meaning_en":"The gopis said among themselves:","page":485,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":485,"meaning_status":"draft"},{"type":"verse","number":[926],"number_text":"੯੨੬।","page":485,"lines":[{"gurmukhi":"ਯਾ ਹੀ ਕੇ ਸੰਗਿ ਸੁਨੋ ਮਿਲ ਕੈ ਹਮ ਕੁੰਜ ਗਲੀਨ ਮੈ ਖੇਲ ਮਚਾਯੋ।","roman":"Yaa hee ke sangi suno mil kai ham kunj galeen mai khel machaayo |","meaning_en":"'Listen: with him we gathered and set up play in the lanes of the groves.","page":485,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਭਯੋ ਸੋਊ ਠਉਰ ਤਹਾ ਹਮ ਹੂੰ ਮਿਲ ਕੈ ਤਹ ਮੰਗਲ ਗਾਯੋ।","roman":"Gaavat bhayo so'oo thaur tahaa ham hoon mil kai tah mangal gaayo |","meaning_en":"He sang in that very place, and there we too together sang songs of joy.","page":485,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਤ੍ਯਾਗਿ ਗਯੋ ਮਥੁਰਾ ਇਨ ਗ੍ਵਾਰਨ ਤੇ ਮਨੂਆ ਉਚਟਾਯੋ।","roman":"So brij tyaagi gayo mathuraa in gvaaran te manooaa uchtaayo |","meaning_en":"He has left Braj and gone to Mathura; his heart has turned away from these milkmaids.'","page":485,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿ ਊਧਵ ਸੋ ਤਿਨ ਟੇਰਿ ਹਹਾ ਹਮਰੇ ਗ੍ਰਿਹਿ ਸ੍ਯਾਮ ਨ ਆਯੋ। ੯੨੬।","roman":"Yau kahi oodhav so tin teri hahaa hamre grihi syaam na aayo | 926 |","meaning_en":"Saying this, they cried out to Udhav, 'Alas, Shyam has not come to our homes!'","page":485,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪਿਨ ਬਾਚ ਊਧਵ ਸੋ","gurmukhi":"ਗੋਪਿਨ ਬਾਚ ਊਧਵ ਸੋ","roman":"Gopin baach oodhav so","meaning_en":"The gopis said to Udhav:","page":485,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":485,"meaning_status":"draft"},{"type":"verse","number":[927],"number_text":"੯੨੭।","page":485,"lines":[{"gurmukhi":"ਏਕ ਸਮੈ ਹਮ ਕੋ ਸੁਨਿ ਊਧਵ ਕੁੰਜਨ ਮੈ ਫਿਰੈ ਸੰਗਿ ਲੀਯੇ।","roman":"Ek samai ham ko suni oodhav kunjan mai phirai sangi leeye |","meaning_en":"'Listen, Udhav: once he roamed the groves taking us along with him.","page":485,"meaning_status":"draft"},{"gurmukhi":"ਹਰਿ ਜੂ ਅਤਿ ਹੀ ਹਿਤ ਸਾਥ ਘਨੇ ਹਮ ਪੈ ਅਤਿ ਹੀ ਕਹਿਯੋ ਪ੍ਰੇਮ ਕੀਯੇ।","roman":"Hari joo ati hee hit saath ghane ham pai ati hee kahiyo prem keeye |","meaning_en":"Hari, with great affection, kept close company with us and showed us great love.","page":485,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕੇ ਬਸਿ ਗਯ ਹਮਰੋ ਮਨ ਹ੍ਵੈ ਅਤਿ ਹੀ ਸੁਖੁ ਭਯੋ ਬ੍ਰਿਜ ਨਾਰਿ ਹੀਯੇ।","roman":"Tin ke basi gay hamro man hvai ati hee sukhu bhayo brij naari heeye |","meaning_en":"Our hearts came under his sway, and the hearts of the women of Braj were very happy.","page":485,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਸੋ ਤਜਿ ਕੈ ਮਥਰਾ ਕੋ ਗਯੋ ਤਿਹ ਕੇ ਬਿਛੁਰੇ ਫਲੁ ਕਵਨ ਜੀਯੇ। ੯੨੭।","roman":"Ab so taji kai mathraa ko gayo tih ke bichhure phalu kavan jeeye | 927 |","meaning_en":"Now he has left us and gone to Mathura; parted from him, what is the use of living?'","page":485,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"The poet said:","page":486,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":486,"meaning_status":"draft"},{"type":"verse","number":[928],"number_text":"੯੨੮।","page":486,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਨਿ ਪੈ ਜਿਤਨੀ ਫੁਨਿ ਊਧਵ ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਬਾਤ ਬਖਾਨੀ।","roman":"Gvaarni pai jitnee phuni oodhav syaam kahai hari baat bakhaanee |","meaning_en":"However much Udhav, says Shyam, set out Hari's message to the milkmaids,","page":486,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਯਾਨ ਕੋ ਉਤਰ ਦੇਤ ਭਈ ਨਹਿ ਪ੍ਰੇਮ ਚਿਤਾਰ ਸਭੇ ਉਚਰਾਨੀ।","roman":"Gyaan ko utar det bhaee nahi prem chitaar sabhe uchraanee |","meaning_en":"they gave no answer to his knowledge; recalling their love, they all spoke of that:","page":486,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹੀ ਕੇ ਦੇਖਤ ਭੋਜਨ ਖਾਤ ਸਖੀ ਜਿਹ ਕੇ ਬਿਨੁ ਪੀਤ ਨ ਪਾਨੀ।","roman":"Jaahee ke dekhat bhojan khaat sakhee jih ke binu peet na paanee |","meaning_en":"'He at the sight of whom we ate our food, friend, without whom we would not drink water...'","page":486,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਯਾਨ ਕੀ ਜੋ ਇਨ ਬਾਤ ਕਹੀ ਤਿਨ ਹੂੰ ਹਿਤ ਸੋ ਕਰਿ ਏਕ ਨ ਜਾਨੀ। ੯੨੮।","roman":"Gyaan kee jo in baat kahee tin hoon hit so kari ek na jaanee | 928 |","meaning_en":"Of the words of knowledge he spoke, they took not a single one to heart.","page":486,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪਿਨ ਬਾਚ ਊਧਵ ਸੋ","gurmukhi":"ਗੋਪਿਨ ਬਾਚ ਊਧਵ ਸੋ","roman":"Gopin baach oodhav so","meaning_en":"The gopis said to Udhav:","page":486,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":486,"meaning_status":"draft"},{"type":"verse","number":[929],"number_text":"੯੨੯।","page":486,"lines":[{"gurmukhi":"ਮਿਲ ਕੈ ਤਿਨ ਊਧਵ ਸੰਗਿ ਕਹਿਯੋ ਹਰਿ ਸੋ ਸੁਨ ਊਧਵ ਯੌ ਕਹੀਯੋ।","roman":"Mil kai tin oodhav sangi kahiyo hari so sun oodhav yau kaheeyo |","meaning_en":"Together they said to Udhav: 'Listen, Udhav, say this to Hari:","page":486,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿ ਕੈ ਕਰਿ ਉਧਵ ਗ੍ਯਾਨ ਜਿਤੋ ਪਠਿਯੋ ਤਿਤਨੋ ਸਭ ਹੀ ਗਹੀਯੋ।","roman":"Kahi kai kari udhav gyaan jito pathiyo titno sabh hee gaheeyo |","meaning_en":"\"All the knowledge you sent through Udhav's telling, we have received it all.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਇਨ ਗ੍ਵਾਰਨਿ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹਿਯੋ ਹਿਤ ਆਖਨ ਸੋ ਚਹੀਯੋ।","roman":"Sabh hee in gvaarni pai kabi syaam kahiyo hit aakhan so chaheeyo |","meaning_en":"On all these milkmaids,\" says the poet Shyam, \"you should look with loving eyes.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਇਨ ਕੋ ਤੁਮ ਤਿਆਗ ਗਏ ਮਥੁਰਾ ਹਮਰੀ ਸੁਧਿ ਲੇਤ ਸਦਾ ਰਹੀਯੋ। ੯੨੯।","roman":"In ko tum tiaag gae mathuraa hamree sudhi let sadaa raheeyo | 929 |","meaning_en":"You left them and went to Mathura; always keep taking news of us.\"'","page":486,"meaning_status":"draft"}]},{"type":"verse","number":[930],"number_text":"੯੩੦।","page":486,"lines":[{"gurmukhi":"ਜਬ ਊਧਵ ਸੋ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਤਬ ਊਧਵ ਕੋ ਮਨ ਪ੍ਰੇਮ ਭਰਿਯੋ ਹੈ।","roman":"Jab oodhav so ih bhaati kahiyo tab oodhav ko man prem bhariyo hai |","meaning_en":"When they spoke thus to Udhav, Udhav's heart was filled with love.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਗਈ ਸੁਧਿ ਭੂਲ ਸਭੈ ਮਨ ਤੇ ਸਭ ਗ੍ਯਾਨ ਹੁਤੋ ਸੁ ਟਰਿਯੋ ਹੈ।","roman":"Aur gaee sudhi bhool sabhai man te sabh gyaan huto su tariyo hai |","meaning_en":"All other awareness slipped from his mind, and all the knowledge he had was set aside.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਮਿਲਿ ਕੈ ਸੰਗਿ ਗ੍ਵਾਰਨਿ ਕੇ ਅਤਿ ਪ੍ਰੀਤਿ ਕੀ ਬਾਤ ਕੇ ਸੰਗਿ ਢਰਿਯੋ ਹੈ।","roman":"So mili kai sangi gvaarni ke ati preeti kee baat ke sangi dhariyo hai |","meaning_en":"Joining with the milkmaids, he melted into talk of deep love,","page":486,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਯਾਨ ਕੇ ਡਾਰ ਮਨੋ ਕਪਰੇ ਹਿਤ ਕੀ ਸਰਿਤਾ ਹਿਤ ਮਹਿ ਕੂਦ ਪਰਿਯੋ ਹੈ। ੯੩੦।","roman":"Gyaan ke daar mano kapre hit kee saritaa hit mahi kood pariyo hai | 930 |","meaning_en":"as if, throwing off the clothes of knowledge, he leaped into the river of love.","page":486,"meaning_status":"draft","note":"ਹਿਤ ਕੀ ਸਰਿਤਾ ਹਿਤ ਮਹਿ: ਹਿਤ repeated; printed so."}]},{"type":"verse","number":[931],"number_text":"੯੩੧।","page":486,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਸੰਗਿ ਗੁਆਰਨਿ ਕੇ ਜਬ ਹੀ ਸਭ ਗ੍ਵਾਰਨਿ ਕੋ ਹਿਤ ਚੀਨੋ।","roman":"Yau kahi sangi guaarni ke jab hee sabh gvaarni ko hit cheeno |","meaning_en":"Speaking thus with the milkmaids, when he recognised the love of all the milkmaids,","page":486,"meaning_status":"draft"},{"gurmukhi":"ਊਧਵ ਗ੍ਯਾਨ ਦਯੋ ਤਜਿ ਕੈ ਮਨ ਮੈ ਜਬ ਪ੍ਰੇਮ ਕੋ ਸੰਗ੍ਰਹ ਕੀਨੋ।","roman":"Oodhav gyaan dayo taji kai man mai jab prem ko sangrah keeno |","meaning_en":"Udhav gave up his knowledge, as he gathered love into his heart.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਹੋਇ ਗਯੋ ਤਨਮੈ ਹਿਤ ਸੋ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਸੁ ਕਰਿਯੋ ਬ੍ਰਿਜ ਹੀਨੋ।","roman":"Hoi gayo tanmai hit so ih bhaati kahiyo su kariyo brij heeno |","meaning_en":"He became absorbed in love and spoke thus: 'He has made Braj bereft.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗਿ ਗਏ ਤੁਮ ਕੋ ਮਥਰਾ ਤਿਹ ਤੇ ਹਰਿ ਕਾਮ ਸਖੀ ਘਟ ਕੀਨੋ। ੯੩੧।","roman":"Tyaagi gae tum ko mathraa tih te hari kaam sakhee ghat keeno | 931 |","meaning_en":"He left you and went to Mathura; in that, friends, Hari has done a mean deed.'","page":486,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਊਧਵ ਬਾਚ ਗੋਪਿਨ ਸੋ","gurmukhi":"ਊਧਵ ਬਾਚ ਗੋਪਿਨ ਸੋ","roman":"Oodhav baach gopin so","meaning_en":"Udhav said to the gopis:","page":486,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":486,"meaning_status":"draft"},{"type":"verse","number":[932],"number_text":"੯੩੨।","page":486,"lines":[{"gurmukhi":"ਜਾਇ ਕੈ ਹਉ ਮਥਰਾ ਮੈ ਸਖੀ ਹਰਿ ਤੇ ਤੁਮ ਲਯੈਬੇ ਕੋ ਦੂਤ ਪਠੈ ਹੋ।","roman":"Jaai kai hau mathraa mai sakhee hari te tum layaibe ko doot pathai ho |","meaning_en":"'Friends, when I go to Mathura I will have Hari send a messenger to fetch you.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਬੀਤਤ ਜੋ ਤੁਮ ਪੈ ਬਿਰਥਾ ਸਭ ਹੀ ਜਦੁਰਾਇ ਕੇ ਪਾਸ ਕਹੈ ਹੋ।","roman":"Beetat jo tum pai birthaa sabh hee jaduraai ke paas kahai ho |","meaning_en":"All the distress that is passing over you, I will tell to the Lord of the Yadavs.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਤੁਮਰੀ ਬਿਨਤੀ ਉਹ ਪੈ ਬਿਧਿ ਜਾ ਰਿਝ ਹੈ ਬਿਧਿ ਤਾ ਰਿਝਵੈ ਹੋ।","roman":"Kai tumree bintee uh pai bidhi jaa rijh hai bidhi taa rijhvai ho |","meaning_en":"Putting your plea to him, in whatever way he is won over, in that way I will win him over.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਪਾਇਨ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਕੌ ਬ੍ਰਿਜ ਭੀਤਰ ਫੇਰਿ ਲਿਯੈ ਹੋ। ੯੩੨।","roman":"Paain pai kabi syaam kahai hari kau brij bheetar pheri liyai ho | 932 |","meaning_en":"Falling at his feet, says the poet Shyam, I will bring Hari back into Braj.'","page":486,"meaning_status":"draft"}]},{"type":"verse","number":[933],"number_text":"੯੩੩।","page":486,"lines":[{"gurmukhi":"ਯੌ ਜਬ ਊਧਵ ਬਾਤ ਕਹੀ ਉਠਿ ਪਾਇਨ ਲਾਗਤ ਭੀ ਤਬ ਸੋਊ।","roman":"Yau jab oodhav baat kahee uthi paain laagat bhee tab so'oo |","meaning_en":"When Udhav spoke thus, they rose and fell at his feet.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਦੂਖ ਘਟਿਓ ਤਿਨ ਕੇ ਮਨ ਤੇ ਅਤਿ ਹੀ ਮਨ ਭੀਤਰ ਆਨੰਦ ਹੋਊ।","roman":"Dookh ghatio tin ke man te ati hee man bheetar aanand ho'oo |","meaning_en":"The pain lessened in their minds, and great joy came within.","page":486,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਬਿਨਤੀ ਸੰਗਿ ਊਧਵ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬਿਧਿ ਯਾ ਉਚਰੋਊ।","roman":"Kai bintee sangi oodhav ke kabi syaam kahai bidhi yaa uchro'oo |","meaning_en":"Making a plea to Udhav, says the poet Shyam, they spoke in this way:","page":486,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਸੋ ਜਾਇ ਕੈ ਯੌ ਕਹੀਯੋ ਕਰਿ ਕੈ ਕਹਿਯੋ ਪ੍ਰੀਤਿ ਨ ਤ੍ਯਾਗਤ ਕੋਊ। ੯੩੩।","roman":"Syaam so jaai kai yau kaheeyo kari kai kahiyo preeti na tyaagat ko'oo | 933 |","meaning_en":"'Go to Shyam and tell him this, tell it plainly: no one abandons love.'","page":486,"meaning_status":"draft"}]},{"type":"verse","number":[934],"number_text":"੯੩੪।","page":487,"lines":[{"gurmukhi":"ਕੁੰਜ ਗਲੀਨ ਮੈ ਖੇਲਤ ਹੀ ਸਭ ਹੀ ਮਨ ਗ੍ਵਾਰਨਿ ਕੋ ਹਰਿਓ।","roman":"Kunj galeen mai khelat hee sabh hee man gvaarni ko hario |","meaning_en":"He who, playing in the lanes of the groves, stole the hearts of all the milkmaids,","page":487,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ ਕੇ ਹਿਤ ਲੋਗਨ ਹਾਸ ਸਹਿਯੋ ਜਿਨ ਕੇ ਹਿਤ ਸਤ੍ਰਨ ਸੋ ਲਰਿਓ।","roman":"Jin ke hit logan haas sahiyo jin ke hit satran so lario |","meaning_en":"who for their sake bore people's mockery, who for their sake fought with enemies,","page":487,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗਿ ਊਧਵ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬਿਨਤੀ ਕਰਿ ਕੈ ਇਮ ਉਚਰਿਓ।","roman":"Sangi oodhav ke kabi syaam kahai bintee kari kai im uchrio |","meaning_en":"to Udhav, says the poet Shyam, they made a plea about him and spoke thus:","page":487,"meaning_status":"draft"},{"gurmukhi":"ਹਮ ਤ੍ਯਾਗਿ ਗਏ ਬ੍ਰਿਜ ਮੈ ਮਥਰਾ ਤਿਹ ਤੇ ਤੁਮ ਕਾਮ ਬੁਰੋ ਕਰਿਓ। ੯੩੪।","roman":"Ham tyaagi gae brij mai mathraa tih te tum kaam buro kario | 934 |","meaning_en":"'You left us in Braj and went to Mathura; in that you did an evil deed.","page":487,"meaning_status":"draft"}]},{"type":"verse","number":[935],"number_text":"੯੩੫।","page":487,"lines":[{"gurmukhi":"ਬ੍ਰਿਜ ਬਾਸਨ ਤ੍ਯਾਗਿ ਗਏ ਮਥੁਰਾ ਪੁਰ ਬਾਸਿਨ ਕੇ ਰਸ ਭੀਤਰ ਪਾਗਿਓ।","roman":"Brij baasan tyaagi gae mathuraa pur baasin ke ras bheetar paagio |","meaning_en":"You left the people of Braj and went to Mathura, steeped in the love of the city women.","page":487,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੇਮ ਜਿਤੋ ਪਰ ਗ੍ਵਾਰਨਿ ਥੋ ਉਨ ਸੰਗਿ ਰਚੇ ਇਨ ਤੇ ਸਭ ਭਾਗਿਓ।","roman":"Prem jito par gvaarni tho un sangi rache in te sabh bhaagio |","meaning_en":"All the love you had for the milkmaids, now that you are absorbed with them, has fled from these.","page":487,"meaning_status":"draft"},{"gurmukhi":"ਦੈ ਤੁਹਿ ਹਾਥਿ ਸੁਨੋ ਬਤੀਯਾ ਹਮ ਜੋਗ ਕੇ ਭੇਖ ਪਠਾਵਨ ਲਾਗਿਓ।","roman":"Dai tuhi haathi suno bateeyaa ham jog ke bhekh pathaavan laagio |","meaning_en":"Listen to our words: placing it in your hands, he has begun to send us the guise of yoga.","page":487,"meaning_status":"draft","note":"Addressed partly to Krishna, partly to Udhav; 'your hands' are Udhav's."},{"gurmukhi":"ਤਾ ਸੰਗਿ ਊਧਵ ਯੌ ਕਹੀਯੋ ਹਰਿ ਜੂ ਤੁਮ ਪ੍ਰੇਮ ਸਭੈ ਅਬ ਤ੍ਯਾਗਿਓ। ੯੩੫।","roman":"Taa sangi oodhav yau kaheeyo hari joo tum prem sabhai ab tyaagio | 935 |","meaning_en":"Udhav, say this to him: \"Hari, you have now abandoned all love.\"'","page":487,"meaning_status":"draft"}]},{"type":"verse","number":[936],"number_text":"੯੩੬।","page":487,"lines":[{"gurmukhi":"ਊਧਵ ਜੋ ਤਜਿ ਕੈ ਬ੍ਰਿਜ ਕੋ ਚਲਿ ਕੈ ਜਬ ਹੀ ਮਥੁਰਾ ਪੁਰਿ ਜਈਯੈ।","roman":"Oodhav jo taji kai brij ko chali kai jab hee mathuraa puri jaeeyai |","meaning_en":"'Udhav, when you leave Braj and go to the city of Mathura,","page":487,"meaning_status":"draft"},{"gurmukhi":"ਪੈ ਅਪੁਨੇ ਚਿਤ ਮੈ ਹਿਤ ਕੈ ਹਮ ਓਰ ਤੇ ਸ੍ਯਾਮ ਕੇ ਪਾਇਨ ਪਈਯੈ।","roman":"Pai apune chit mai hit kai ham or te syaam ke paain paeeyai |","meaning_en":"then, with love in your own heart, fall at Shyam's feet on our behalf;","page":487,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਅਤਿ ਹੀ ਬਿਨਤੀ ਤਿਹ ਪੈ ਫਿਰ ਕੈ ਇਹ ਭਾਤਿ ਸੋ ਉਤਰ ਦਈਯੈ।","roman":"Kai ati hee bintee tih pai phir kai ih bhaati so utar daeeyai |","meaning_en":"pleading with him earnestly, then give him this answer in this way:","page":487,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੀਤਿ ਨਿਬਾਹੀਯੈ ਤਉ ਕਰੀਯੈ ਪਰ ਯੌ ਨਹੀ ਕਾਹੂੰ ਸੋ ਪ੍ਰੀਤਿ ਕਰਈਯੈ। ੯੩੬।","roman":"Preeti nibaaheeyai tau kareeyai par yau nahee kaahoon so preeti karaeeyai | 936 |","meaning_en":"\"Love should be made only if it is kept up; one should not make love with anyone like this.\"'","page":487,"meaning_status":"draft"}]},{"type":"verse","number":[937],"number_text":"੯੩੭।","page":487,"lines":[{"gurmukhi":"ਊਧਵ ਮੋ ਸੁਨ ਲੈ ਬਤੀਯਾ ਜਦੁਬੀਰ ਕੋ ਧ੍ਯਾਨ ਜਬੈ ਕਰਿ ਹੋ।","roman":"Oodhav mo sun lai bateeyaa jadubeer ko dhyaan jabai kari ho |","meaning_en":"'Udhav, hear my words: whenever I meditate on the Yadav hero,","page":487,"meaning_status":"draft"},{"gurmukhi":"ਬਿਰਹਾ ਤਬ ਆਇ ਕੈ ਮੋਹਿ ਗ੍ਰਸੈ ਤਿਹ ਕੇ ਗ੍ਰਸਏ ਨ ਜੀਯੋ ਮਰਿ ਹੋ।","roman":"Birhaa tab aai kai mohi grasai tih ke grasae na jeeyo mari ho |","meaning_en":"separation comes then and seizes me; seized by it, I neither live nor die.","page":487,"meaning_status":"draft"},{"gurmukhi":"ਨ ਕਛੂ ਸੁਧਿ ਮੋ ਤਨ ਮੈ ਰਹਿ ਹੈ ਧਰਨੀ ਪਰ ਹ੍ਵੈ ਬਿਸੁਧੀ ਝਰਿ ਹੋ।","roman":"Na kachhoo sudhi mo tan mai rahi hai dharnee par hvai bisudhee jhari ho |","meaning_en":"No awareness remains in my body; I fall to the earth senseless.","page":487,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਤੇ ਹਮ ਕੋ ਬ੍ਰਿਥਾ ਕਹੀਐ ਕਿਹ ਭਾਤਿ ਸੋ ਧੀਰਜ ਹਉ ਧਰਿ ਹੋ। ੯੩੭।","roman":"Tih te ham ko brithaa kaheeai kih bhaati so dheeraj hau dhari ho | 937 |","meaning_en":"So tell him of my plight: how shall I keep my patience?'","page":487,"meaning_status":"draft","note":"ਬ੍ਰਿਥਾ: read as 'plight'; the line may instead ask Udhav 'tell me how I shall keep patience'."}]},{"type":"verse","number":[938],"number_text":"੯੩੮।","page":487,"lines":[{"gurmukhi":"ਦੀਨ ਹ੍ਵੈ ਗ੍ਵਾਰਨਿ ਸੋਊ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਜੁ ਥੀ ਅਤਿ ਹੀ ਅਭਿਮਾਨੀ।","roman":"Deen hvai gvaarni so'oo kahai kabi syaam ju thee ati hee abhimaanee |","meaning_en":"That milkmaid, says the poet Shyam, who had been so very proud, speaks humbly,","page":487,"meaning_status":"draft"},{"gurmukhi":"ਕੰਚਨ ਸੇ ਤਨ ਕੰਜ ਮੁਖੀ ਜੋਊ ਰੂਪ ਬਿਖੈ ਰਤਿ ਕੀ ਫੁਨਿ ਸਾਨੀ।","roman":"Kanchan se tan kanj mukhee jo'oo roop bikhai rati kee phuni saanee |","meaning_en":"she with a body like gold and a lotus face, who in beauty was like Rati herself.","page":487,"meaning_status":"draft","note":"Rati: wife of the god of love."},{"gurmukhi":"ਯੌ ਕਹੈ ਬ੍ਯਾਕੁਲ ਹ੍ਵੈ ਬਤੀਯਾ ਕਬਿ ਨੇ ਤਿਹ ਕੀ ਉਪਮਾ ਪਹਿਚਾਨੀ।","roman":"Yau kahai byaakul hvai bateeyaa kabi ne tih kee upmaa pahichaanee |","meaning_en":"Distressed, she speaks these words; the poet has found a simile for it:","page":487,"meaning_status":"draft"},{"gurmukhi":"ਊਧਵ ਗ੍ਵਾਰਨੀਯਾ ਸਫਰੀ ਸਭ ਨਾਮ ਲੈ ਸ੍ਯਾਮ ਕੋ ਜੀਵਤ ਪਾਨੀ। ੯੩੮।","roman":"Oodhav gvaarneeyaa saphree sabh naam lai syaam ko jeevat paanee | 938 |","meaning_en":"'Udhav, the milkmaids are all fish; the name of Shyam is the water by which they live.'","page":487,"meaning_status":"draft","note":"ਸਫਰੀ: small fish."}]},{"type":"verse","number":[939],"number_text":"੯੩੯।","page":487,"lines":[{"gurmukhi":"ਆਤੁਰ ਹ੍ਵੈ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਸੰਗਿ ਊਧਵ ਕੇ ਸੁ ਕਹਿਯੋ ਇਮ ਬੈਨਾ।","roman":"Aatur hvai brikhbhaan sutaa sangi oodhav ke su kahiyo im bainaa |","meaning_en":"In distress the daughter of Brikhbhan spoke these words to Udhav:","page":487,"meaning_status":"draft"},{"gurmukhi":"ਭੂਖਨ ਭੋਜਨ ਧਾਮ ਜਿਤੋ ਹਮ ਕੇ ਜਦੁਬੀਰ ਬਿਨਾ ਸੁ ਰੁਚੈ ਨਾ।","roman":"Bhookhan bhojan dhaam jito ham ke jadubeer binaa su ruchai naa |","meaning_en":"'Ornaments, food, home, all that we have: without the Yadav hero, nothing pleases.'","page":487,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿ ਸ੍ਯਾਮ ਬਿਯੋਗ ਬਿਖੈ ਬਸਿ ਗੇ ਕਬਿ ਨੇ ਜਸ ਯੌ ਉਚਰੈਨਾ।","roman":"Yau kahi syaam biyog bikhai basi ge kabi ne jas yau uchrainaa |","meaning_en":"Saying this she sank into separation from Shyam; the poet has told its praise thus:","page":487,"meaning_status":"draft"},{"gurmukhi":"ਰੋਵਤ ਭੀ ਅਤਿ ਹੀ ਦੁਖ ਸੋ ਜੁ ਹੁਤੇ ਮਨੋ ਬਾਲ ਕੇ ਕੰਜਨ ਨੈਨਾ। ੯੩੯।","roman":"Rovat bhee ati hee dukh so ju hute mano baal ke kanjan nainaa | 939 |","meaning_en":"she wept in great grief, the maiden whose eyes were like lotuses.","page":487,"meaning_status":"draft"}]},{"type":"verse","number":[940],"number_text":"੯੪੦।","page":487,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਅਤਿ ਪ੍ਰੇਮ ਛਕੀ ਮਨ ਮੈ ਜਦੁਬੀਰ ਕੋ ਧਿਆਨ ਲਗੈ ਕੈ।","roman":"Brikhbhaan sutaa ati prem chhakee man mai jadubeer ko dhiaan lagai kai |","meaning_en":"Brikhbhan's daughter, overflowing with love, fixing her mind on the Yadav hero,","page":487,"meaning_status":"draft"},{"gurmukhi":"ਰੋਵਤ ਭੀ ਅਤਿ ਹੀ ਦੁਖ ਸੋ ਸੰਗ ਕਾਜਰ ਨੀਰ ਗਿਰਿਯੋ ਢਰ ਕੈ ਕੈ।","roman":"Rovat bhee ati hee dukh so sang kaajar neer giriyo dhar kai kai |","meaning_en":"wept in great grief, and tears mixed with collyrium rolled down and fell.","page":487,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਉਚ ਮਹਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹਿਯੋ ਮੁਖ ਤੇ ਉਮਗੈ ਕੈ।","roman":"Taa chhabi ko jasu uch mahaa kabi syaam kahiyo mukh te umgai kai |","meaning_en":"The great poet Shyam told its lofty praise, with eager lips:","page":487,"meaning_status":"draft"},{"gurmukhi":"ਚੰਦਹਿ ਕੋ ਜੁ ਕਲੰਕ ਹੁਤੋ ਮਨੋ ਨੈਨਨਿ ਪੈਡ ਚਲ੍ਯੋ ਨਿਚੁਰੈ ਕੈ। ੯੪੦।","roman":"Chandhi ko ju kalank huto mano nainni paid chalyo nichurai kai | 940 |","meaning_en":"it was as if the moon's dark mark were being wrung out and flowing down the path of her eyes.","page":487,"meaning_status":"draft"}]},{"type":"verse","number":[941],"number_text":"੯੪੧।","page":488,"lines":[{"gurmukhi":"ਗਹਿ ਧੀਰਜ ਊਧਵ ਸੋ ਬਚਨਾ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਇਹ ਭਾਤਿ ਉਚਾਰੇ।","roman":"Gahi dheeraj oodhav so bachnaa brikhbhaan sutaa ih bhaati uchaare |","meaning_en":"Taking courage, Brikhbhan's daughter spoke these words to Udhav:","page":488,"meaning_status":"draft"},{"gurmukhi":"ਨੇਹੁ ਤਜਿਯੋ ਬ੍ਰਿਜ ਬਾਸਨ ਸੋ ਤਿਹ ਤੇ ਕਛੂ ਜਾਨਤ ਦੋਖ ਬਿਚਾਰੇ।","roman":"Nehu tajiyo brij baasan so tih te kachhoo jaanat dokh bichaare |","meaning_en":"'He has given up love for the people of Braj; so he must think these poor women have some fault.","page":488,"meaning_status":"draft","note":"Sense uncertain."},{"gurmukhi":"ਬੈਠਿ ਗਏ ਰਥ ਭੀਤਰ ਆਪ ਨਹੀ ਇਨ ਕੀ ਸੋਊ ਓਰਿ ਨਿਹਾਰੇ।","roman":"Baithi gae rath bheetar aap nahee in kee so'oo ori nihaare |","meaning_en":"He sat down in the chariot himself and did not even look towards them.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗਿ ਗਏ ਬ੍ਰਿਜ ਕੋ ਮਥੁਰਾ ਹਮ ਜਾਨਤ ਹੈ ਘਟ ਭਾਗ ਹਮਾਰੇ। ੯੪੧।","roman":"Tyaagi gae brij ko mathuraa ham jaanat hai ghat bhaag hamaare | 941 |","meaning_en":"He left Braj and went to Mathura; we know our fortune is poor.'","page":488,"meaning_status":"draft"}]},{"type":"verse","number":[942],"number_text":"੯੪੨।","page":488,"lines":[{"gurmukhi":"ਜਬ ਜੈਹੋ ਕਹਿਯੋ ਮਥੁਰਾ ਕੈ ਬਿਖੈ ਹਰਿ ਪੈ ਹਮਰੀ ਬਿਨਤੀ ਇਹ ਕੀਜੋ।","roman":"Jab jaiho kahiyo mathuraa kai bikhai hari pai hamree bintee ih keejo |","meaning_en":"'When you go to Mathura, make this plea of ours to Hari:","page":488,"meaning_status":"draft"},{"gurmukhi":"ਪਾਇਨ ਕੋ ਗਹਿ ਕੈ ਰਹੀਯੋ ਘਟਕਾ ਦਸ ਜੋ ਮੁਹਿ ਨਾਮਹਿ ਲੀਜੋ।","roman":"Paain ko gahi kai raheeyo ghatkaa das jo muhi naamhi leejo |","meaning_en":"hold his feet for ten gharis, and take my name.","page":488,"meaning_status":"draft","note":"ਘਟਕਾ: a ghari, a period of about 24 minutes."},{"gurmukhi":"ਤਾਹੀ ਕੇ ਪਾਛੇ ਤੇ ਮੋ ਬਤੀਯਾ ਸੁਨਿ ਲੈ ਇਹ ਭਾਤਹਿ ਸੋ ਉਚਰੀਜੋ।","roman":"Taahee ke paachhe te mo bateeyaa suni lai ih bhaathi so uchreejo |","meaning_en":"After that, hear my words and speak them to him in this way:","page":488,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨਤ ਹੋ ਹਿਤ ਤ੍ਯਾਗ ਗਏ ਕਬਹੂੰ ਹਮਰੇ ਹਿਤ ਕੇ ਸੰਗ ਭੀਜੋ। ੯੪੨।","roman":"Jaanat ho hit tyaag gae kabhoon hamre hit ke sang bheejo | 942 |","meaning_en":"\"I know you have given up love; were you ever steeped in our love at all?\"'","page":488,"meaning_status":"draft","note":"Read as a question; it may also be a plea, 'at some time be steeped in our love'; uncertain."}]},{"type":"verse","number":[943],"number_text":"੯੪੩।","page":488,"lines":[{"gurmukhi":"ਊਧਵ ਕੋ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਬਚਨਾ ਇਹ ਭਾਤਿ ਸੋ ਉਚਰਿਯੋ ਹੈ।","roman":"Oodhav ko brikhbhaan sutaa bachnaa ih bhaati so uchriyo hai |","meaning_en":"Brikhbhan's daughter spoke these words to Udhav in this way,","page":488,"meaning_status":"draft"},{"gurmukhi":"ਤਿਆਗ ਦਈ ਜਬ ਅਉਰ ਕਥਾ ਮਨ ਜਉ ਸੰਗਿ ਸ੍ਯਾਮ ਕੇ ਪ੍ਰੇਮ ਭਰਿਯੋ ਹੈ।","roman":"Tiaag daee jab aur kathaa man jau sangi syaam ke prem bhariyo hai |","meaning_en":"when she had given up all other talk and her heart was filled with love for Shyam:","page":488,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਸੰਗ ਸੋਊ ਕਹੋ ਬਤੀਯਾ ਬਨ ਮੈ ਹਮਰੋ ਜੋਊ ਸੰਗਿ ਅਰਿਯੋ ਹੈ।","roman":"Taa sang so'oo kaho bateeyaa ban mai hamro jo'oo sangi ariyo hai |","meaning_en":"'Tell him of that, how he held out against me in the forest:","page":488,"meaning_status":"draft","note":"ਅਰਿਯੋ: read as 'was stubborn, held out'; uncertain."},{"gurmukhi":"ਮੈ ਤੁਮਰੇ ਸੰਗਿ ਮਾਨ ਕਰਿਯੋ ਤੁਮ ਹੂੰ ਹਮਰੇ ਸੰਗ ਮਾਨ ਕਰਿਯੋ ਹੈ। ੯੪੩।","roman":"Mai tumre sangi maan kariyo tum hoon hamre sang maan kariyo hai | 943 |","meaning_en":"\"I sulked with you, and you too sulked with me.\"'","page":488,"meaning_status":"draft","note":"ਮਾਨ: a lover's pique."}]},{"type":"verse","number":[944],"number_text":"੯੪੪।","page":488,"lines":[{"gurmukhi":"ਬਨ ਮੈ ਹਮਰੋ ਸੰਗਿ ਕੇਲ ਕਰੇ ਮਨ ਮੈ ਅਬ ਸੋ ਜਦੁਬੀਰ ਚਿਤਾਰੋ।","roman":"Ban mai hamro sangi kel kare man mai ab so jadubeer chitaaro |","meaning_en":"'Remember now in your mind, Yadav hero, the sports you played with me in the forest.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਮੋਰੇ ਜੁ ਸੰਗਿ ਕਹੀ ਬਤੀਯਾ ਹਿਤ ਕੀ ਸੋਈ ਅਪਨੇ ਚਿਤ ਨਿਹਾਰੋ।","roman":"More ju sangi kahee bateeyaa hit kee soee apne chit nihaaro |","meaning_en":"Look into your heart at the words of love you spoke with me.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹੀ ਕੋ ਧ੍ਯਾਨ ਕਰੋ ਕਿਹ ਹੇਤ ਤਜਿਯੋ ਬ੍ਰਿਜ ਔ ਮਥੁਰਾ ਕੋ ਪਧਾਰੋ।","roman":"Taahee ko dhyaan karo kih het tajiyo brij au mathuraa ko padhaaro |","meaning_en":"Think on this: why did you leave Braj and go off to Mathura?","page":488,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨਤ ਹੈ ਤੁਮਰੋ ਕਛੁ ਦੋਸ ਨਹੀ ਕਛੁ ਹੈ ਘਟ ਭਾਗ ਹਮਾਰੋ। ੯੪੪।","roman":"Jaanat hai tumro kachhu dos nahee kachhu hai ghat bhaag hamaaro | 944 |","meaning_en":"We know the fault is not yours at all; it is our fortune that is poor.'","page":488,"meaning_status":"draft"}]},{"type":"verse","number":[945],"number_text":"੯੪੫।","page":488,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਉਤਰ ਦੇਤ ਭਯੋ ਊਧਵ ਪ੍ਰੀਤਿ ਘਨੀ ਹਰਿ ਕੀ ਸੰਗ ਤੇਰੈ।","roman":"Yau suni utar det bhayo oodhav preeti ghanee hari kee sang terai |","meaning_en":"Hearing this, Udhav gave answer: 'Hari's love for you is deep.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨਤ ਹੋ ਅਬ ਆਵਤ ਹੈ ਉਪਜੈ ਇਹ ਚਿੰਤ ਕਹਿਯੋ ਮਨ ਮੇਰੈ।","roman":"Jaanat ho ab aavat hai upjai ih chint kahiyo man merai |","meaning_en":"I think he will come now; this thought arises in my mind.'","page":488,"meaning_status":"draft"},{"gurmukhi":"ਕਿਉ ਮਥਰਾ ਤਜਿ ਆਵਤ ਹੈ ਜੁ ਫਿਰੈ ਨਹਿ ਗ੍ਵਾਰਨਿ ਕੇ ਫੁਨਿ ਫੇਰੈ।","roman":"Kiu mathraa taji aavat hai ju phirai nahi gvaarni ke phuni pherai |","meaning_en":"'Why would he leave Mathura and come, he who does not return though the milkmaids call him back?","page":488,"meaning_status":"draft","note":"Speaker of lines 3-4 probably Radha, replying; uncertain."},{"gurmukhi":"ਜਾਨਤ ਹੈ ਹਮਰੇ ਘਟਿ ਭਾਗਨ ਆਵਤ ਹੈ ਹਰਿ ਜੂ ਫਿਰਿ ਡੇਰੈ। ੯੪੫।","roman":"Jaanat hai hamre ghati bhaagan aavat hai hari joo phiri derai | 945 |","meaning_en":"We know that, with our poor fortune, Hari will not come back to his dwelling.'","page":488,"meaning_status":"draft","note":"ਆਵਤ ਹੈ ... ਫਿਰਿ ਡੇਰੈ: read as 'will (not) come back home'; uncertain."}]},{"type":"verse","number":[946],"number_text":"੯੪੬।","page":488,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਰੋਵਤ ਭੀ ਲਲਨਾ ਅਪਨੇ ਮਨ ਮੈ ਅਤਿ ਸੋਕ ਬਢਾਯੋ।","roman":"Yau kahi rovat bhee lalnaa apne man mai ati sok badhaayo |","meaning_en":"Saying this, the young woman wept, her grief growing greatly in her mind.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਝੂਮਿ ਗਿਰੀ ਪ੍ਰਿਥਮੀ ਪਰ ਸੋ ਹ੍ਰਿਦੈ ਆਨੰਦ ਥੋ ਤਿਤਨੋ ਬਿਸਰਾਯੋ।","roman":"Jhoomi giree prithmee par so hridai aanand tho titno bisraayo |","meaning_en":"Swaying, she fell to the earth; all the joy in her heart she forgot.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਭੂਲ ਗਈ ਸੁਧਿ ਅਉਰ ਸਬੈ ਹਰਿ ਕੇ ਮਨ ਧ੍ਯਾਨ ਬਿਖੈ ਤਿਨ ਲਾਯੋ।","roman":"Bhool gaee sudhi aur sabai hari ke man dhyaan bikhai tin laayo |","meaning_en":"She forgot all other awareness and fixed her mind in meditation on Hari.","page":488,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿ ਊਧਵ ਸੋ ਤਿਨਿ ਟੇਰਿ ਹਹਾ ਹਮਰੇ ਗ੍ਰਿਹਿ ਸ੍ਯਾਮ ਨ ਆਯੋ। ੯੪੬।","roman":"Yau kahi oodhav so tini teri hahaa hamre grihi syaam na aayo | 946 |","meaning_en":"Saying this, they cried out to Udhav, 'Alas, Shyam has not come to our homes!'","page":488,"meaning_status":"draft"}]},{"type":"verse","number":[947],"number_text":"੯੪੭।","page":488,"lines":[{"gurmukhi":"ਜਾਹੀ ਕੇ ਸੰਗਿ ਸੁਨੋ ਮਿਲ ਕੈ ਹਮ ਕੁੰਜ ਗਲੀਨ ਮੈ ਖੇਲ ਮਚਾਯੋ।","roman":"Jaahee ke sangi suno mil kai ham kunj galeen mai khel machaayo |","meaning_en":"'Listen: he with whom we gathered and set up play in the lanes of the groves,","page":488,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਭਯੋ ਸੋਊ ਠਉਰ ਤਹਾ ਹਮਹੂੰ ਮਿਲ ਕੈ ਤਹ ਮੰਗਲ ਗਾਯੋ।","roman":"Gaavat bhayo so'oo thaur tahaa hamhoon mil kai tah mangal gaayo |","meaning_en":"he sang in that very place, and there we too together sang songs of joy;","page":488,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਤ੍ਯਾਗਿ ਗਏ ਮਥੁਰਾ ਇਨ ਗ੍ਵਾਰਨਿ ਤੇ ਮਨੂਆ ਉਚਟਾਯੋ।","roman":"So brij tyaagi gae mathuraa in gvaarni te manooaa uchtaayo |","meaning_en":"he has left Braj and gone to Mathura; his heart has turned away from these milkmaids.'","page":488,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿ ਊਧਵ ਸੋ ਤਿਨ ਟੇਰਿ ਹਹਾ ਹਮਰੇ ਗ੍ਰਿਹਿ ਸ੍ਯਾਮ ਨ ਆਯੋ। ੯੪੭।","roman":"Yau kahi oodhav so tin teri hahaa hamre grihi syaam na aayo | 947 |","meaning_en":"Saying this, they cried out to Udhav, 'Alas, Shyam has not come to our homes!'","page":488,"meaning_status":"draft"}]},{"type":"verse","number":[948],"number_text":"੯੪੮।","page":489,"lines":[{"gurmukhi":"ਬ੍ਰਿਜ ਤ੍ਯਾਗਿ ਗਯੋ ਮਥਰਾ ਕੋ ਸੋਊ ਮਨ ਤੇ ਸਭ ਹੀ ਬ੍ਰਿਜ ਨਾਥਿ ਬਿਸਾਰੀ।","roman":"Brij tyaagi gayo mathraa ko so'oo man te sabh hee brij naathi bisaaree |","meaning_en":"'He has left Braj and gone to Mathura; the Lord of Braj has put everything out of his mind.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗਿ ਰਚੇ ਪੁਰ ਬਾਸਿਨ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸੋਊ ਜਾਨਿ ਪਿਆਰੀ।","roman":"Sangi rache pur baasin ke kabi syaam kahai so'oo jaani piaaree |","meaning_en":"He is absorbed with the city women, says the poet Shyam, counting them dear.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਊਧਵ ਜੂ ਸੁਨੀਯੈ ਬਿਰਥਾ ਤਿਹ ਤੇ ਅਤਿ ਬ੍ਯਾਕੁਲ ਭੀ ਬ੍ਰਿਜ ਨਾਰੀ।","roman":"Oodhav joo suneeyai birthaa tih te ati byaakul bhee brij naaree |","meaning_en":"Udhav, hear our plight: because of this the women of Braj are greatly distressed.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਕੰਚੁਰੀ ਜਿਉ ਅਹਿਰਾਜ ਤਜੈ ਤਿਹ ਭਾਤਿ ਤਜੀ ਬ੍ਰਿਜ ਨਾਰ ਮੁਰਾਰੀ। ੯੪੮।","roman":"Kanchuree jiu ahiraaj tajai tih bhaati tajee brij naar muraaree | 948 |","meaning_en":"As the king of serpents casts off its slough, so Murari has cast off the women of Braj.'","page":489,"meaning_status":"draft","note":"ਕੰਚੁਰੀ: a snake's shed skin. Murari: Krishna."}]},{"type":"verse","number":[949],"number_text":"੯੪੯।","page":489,"lines":[{"gurmukhi":"ਊਧਵ ਕੇ ਫਿਰਿ ਸੰਗ ਕਹਿਯੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬ੍ਰਿਖਭਾਨ ਜਈ ਹੈ।","roman":"Oodhav ke phiri sang kahiyo kabi syaam kahai brikhbhaan jaee hai |","meaning_en":"Again, says the poet Shyam, the daughter of Brikhbhan spoke to Udhav,","page":489,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਮੁਖ ਕੇ ਸਮ ਚੰਦ੍ਰ ਪ੍ਰਭਾ ਜੁ ਤਿਹੂੰ ਪੁਰ ਮਾਨਹੁ ਰੂਪ ਮਈ ਹੈ।","roman":"Jaa mukh ke sam chandr prabhaa ju tihoon pur maanhu roop maee hai |","meaning_en":"she whose face has the splendour of the moon, as if she were beauty itself in the three worlds:","page":489,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਗਯੋ ਤਜਿ ਕੈ ਬ੍ਰਿਜ ਕੋ ਤਿਹ ਤੇ ਅਤਿ ਬ੍ਯਾਕੁਲ ਚਿਤ ਭਈ ਹੈ।","roman":"Syaam gayo taji kai brij ko tih te ati byaakul chit bhaee hai |","meaning_en":"'Shyam has left Braj; from that my heart has become greatly distressed.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਦਿਨ ਕੇ ਮਥੁਰਾ ਮੈ ਗਏ ਬਿਨੁ ਤ੍ਵੈ ਹਮਰੀ ਸੁਧਿ ਹੂੰ ਨ ਲਈ ਹੈ। ੯੪੯।","roman":"Jaa din ke mathuraa mai gae binu tvai hamree sudhi hoon na laee hai | 949 |","meaning_en":"Since the day he went to Mathura, he has not taken any news of us except through you.","page":489,"meaning_status":"draft"}]},{"type":"verse","number":[950],"number_text":"੯੫੦।","page":489,"lines":[{"gurmukhi":"ਜਾ ਦਿਨ ਕੇ ਬ੍ਰਿਜ ਤ੍ਯਾਗਿ ਗਏ ਬਿਨ ਤ੍ਵੈ ਕੋਊ ਮਾਨਸ ਹੂੰ ਨ ਪਠਾਯੋ।","roman":"Jaa din ke brij tyaagi gae bin tvai ko'oo maanas hoon na pathaayo |","meaning_en":"Since the day he left Braj, he has sent no one at all except you.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਹੇਤ ਜਿਤੋ ਇਨ ਊਪਰ ਥੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤਿਤਨੋ ਬਿਸਰਾਯੋ।","roman":"Het jito in oopar tho kabi syaam kahai titno bisraayo |","meaning_en":"All the love he had for these women, says the poet Shyam, he has forgotten.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਆਪ ਰਚੇ ਪੁਰ ਬਾਸਿਨ ਸੋ ਇਨ ਕੋ ਦੁਖੁ ਦੈ ਉਨ ਕੋ ਰਿਝਵਾਯੋ।","roman":"Aap rache pur baasin so in ko dukhu dai un ko rijhvaayo |","meaning_en":"He himself is absorbed with the city women; giving these women pain, he has pleased those.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਸੰਗ ਜਾਇ ਕੋ ਯੌ ਕਹੀਯੋ ਹਰਿ ਜੀ ਤੁਮਰੇ ਕਹੁ ਕਾ ਜੀਯ ਆਯੋ। ੯੫੦।","roman":"Taa sang jaai ko yau kaheeyo hari jee tumre kahu kaa jeey aayo | 950 |","meaning_en":"Go and say this to him: \"Hari, tell me, what has come into your heart?\"'","page":489,"meaning_status":"draft"}]},{"type":"verse","number":[951],"number_text":"੯੫੧।","page":489,"lines":[{"gurmukhi":"ਤ੍ਯਾਗਿ ਗਏ ਮਥੁਰਾ ਬ੍ਰਿਜ ਕਉ ਚਲਿ ਕੈ ਫਿਰਿ ਆਪ ਨਹੀ ਬ੍ਰਿਜ ਆਏ।","roman":"Tyaagi gae mathuraa brij kau chali kai phiri aap nahee brij aae |","meaning_en":"'He left Braj and went to Mathura, and has not come back to Braj himself.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗਿ ਰਚੇ ਪੁਰਬਾਸਿਨ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮਨ ਆਨੰਦ ਪਾਏ।","roman":"Sangi rache purbaasin ke kabi syaam kahai man aanand paae |","meaning_en":"He is absorbed with the city women, says the poet Shyam, and has found joy of heart.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਦੈ ਗਯੋ ਹੈ ਇਨ ਕੋ ਦੁਖ ਊਧਵ ਪੈ ਮਨ ਮੈ ਨ ਹੁਲਾਸ ਬਢਾਏ।","roman":"Dai gayo hai in ko dukh oodhav pai man mai na hulaas badhaae |","meaning_en":"Udhav, he has given these women pain, and no joy has grown in their hearts.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਆਪ ਨ ਥੇ ਬ੍ਰਿਜ ਮੈ ਉਪਜੇ ਇਨ ਸੋ ਸੁ ਭਏ ਛਿਨ ਬੀਚ ਪਰਾਏ। ੯੫੧।","roman":"Aap na the brij mai upje in so su bhae chhin beech paraae | 951 |","meaning_en":"It is as if he had not been born in Braj; in a moment he has become a stranger to them.'","page":489,"meaning_status":"draft"}]},{"type":"verse","number":[952],"number_text":"੯੫੨।","page":489,"lines":[{"gurmukhi":"ਤ੍ਯਾਗਿ ਗਏ ਨ ਲਈ ਇਨ ਕੀ ਸੁਧਿ ਹੋਤ ਕਛੂ ਮਨਿ ਮੋਹ ਤੁਹਾਰੇ।","roman":"Tyaagi gae na laee in kee sudhi hot kachhoo mani moh tuhaare |","meaning_en":"'You left and took no news of them; is there any affection in your heart?","page":489,"meaning_status":"draft"},{"gurmukhi":"ਆਪ ਰਚੇ ਪੁਰ ਬਾਸਿਨ ਸੋ ਇਨ ਕੇ ਸਭ ਪ੍ਰੇਮ ਬਿਦਾ ਕਰਿ ਡਾਰੇ।","roman":"Aap rache pur baasin so in ke sabh prem bidaa kari daare |","meaning_en":"You yourself are absorbed with the city women, and have dismissed all their love.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਨ ਮਾਨ ਕਰੋ ਫਿਰਿ ਆਵਹੁ ਜੀਤਤ ਭੇ ਤੁਮ ਹੂੰ ਹਮ ਹਾਰੇ।","roman":"Taa te na maan karo phiri aavhu jeetat bhe tum hoon ham haare |","meaning_en":"So do not be proud; come back: you have won and we have lost.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਤਜੋ ਮਥੁਰਾ ਫਿਰਿ ਆਵਹੁ ਹੇ ਸਭ ਗਊਅਨ ਕੇ ਰਖਵਾਰੇ। ੯੫੨।","roman":"Taa te tajo mathuraa phiri aavhu he sabh gaooan ke rakhvaare | 952 |","meaning_en":"So leave Mathura and come back, O protector of all the cows!'","page":489,"meaning_status":"draft"}]},{"type":"verse","number":[953],"number_text":"੯੫੩।","page":489,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਚਿਤਾਰ ਕੈ ਸ੍ਯਾਮ ਕਹੈ ਮਨ ਮੈ ਸਭ ਗ੍ਵਾਰਨੀਯਾ ਦੁਖ ਪਾਵੈ।","roman":"Syaam chitaar kai syaam kahai man mai sabh gvaarneeyaa dukh paavai |","meaning_en":"Remembering Shyam, says Shyam, all the milkmaids suffer in their hearts.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਪਰੈ ਮੁਰਝਾਇ ਧਰਾ ਇਕ ਬਿਯੋਗ ਭਰੀ ਗੁਨ ਬਿਯੋਗ ਹੀ ਗਾਵੈ।","roman":"Ek parai murjhaai dharaa ik biyog bharee gun biyog hee gaavai |","meaning_en":"One falls fainting to the ground; another, filled with separation, sings only songs of separation.","page":489,"meaning_status":"draft"},{"gurmukhi":"ਕੋਊ ਕਹੈ ਜਦੁਰਾ ਮੁਖ ਤੇ ਸੁਨਿ ਸ੍ਰਉਨਨ ਬਾਤ ਤਹਾ ਏਊ ਧਾਵੈ।","roman":"Ko'oo kahai jaduraa mukh te suni sraunan baat tahaa eoo dhaavai |","meaning_en":"If anyone says 'the Yadav king' aloud, hearing the words with their ears they run there.","page":489,"meaning_status":"draft","note":"ਜਦੁਰਾ: printed so; read as 'Yadav king'."},{"gurmukhi":"ਜਉ ਪਿਖਵੈ ਨ ਤਹਾ ਤਿਨ ਕੋ ਸੁ ਕਹੈ ਹਮ ਕੋ ਹਰਿ ਹਾਥਿ ਨ ਆਵੈ। ੯੫੩।","roman":"Jau pikhvai na tahaa tin ko su kahai ham ko hari haathi na aavai | 953 |","meaning_en":"When they do not see him there, they say, 'Hari does not come into our hands.'","page":489,"meaning_status":"draft"}]},{"type":"verse","number":[954],"number_text":"੯੫੪।","page":490,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਨਿ ਬ੍ਯਾਕੁਲ ਚਿਤ ਭਈ ਹਰਿ ਕੇ ਨਹੀ ਆਵਨ ਕੀ ਸੁਧਿ ਪਾਈ।","roman":"Gvaarni byaakul chit bhaee hari ke nahee aavan kee sudhi paaee |","meaning_en":"The milkmaids were troubled at heart; they heard no news of Hari's coming.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਯਾਕੁਲ ਹੋਇ ਗਈ ਚਿਤ ਮੈ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਮਨ ਮੈ ਮੁਰਝਾਈ।","roman":"Byaakul hoi gaee chit mai brikhbhaan sutaa man mai murjhaaee |","meaning_en":"Brikhbhan's daughter became troubled at heart and withered within.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਬਿਰਥਾ ਮਨ ਬੀਚ ਹੁਤੀ ਸੋਊ ਊਧਵ ਕੇ ਤਿਹ ਪਾਸ ਸੁਨਾਈ।","roman":"Jo birthaa man beech hutee so'oo oodhav ke tih paas sunaaee |","meaning_en":"The distress that was in her heart, she told it to Udhav:","page":490,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਨ ਆਵਤ ਹੈ ਤਿਹ ਤੇ ਅਤਿ ਹੀ ਦੁਖ ਭਯੋ ਬਰਨਿਯੋ ਨਹੀ ਜਾਈ। ੯੫੪।","roman":"Syaam na aavat hai tih te ati hee dukh bhayo barniyo nahee jaaee | 954 |","meaning_en":"'Shyam does not come, and from that there is great pain, which cannot be described.'","page":490,"meaning_status":"draft"}]},{"type":"verse","number":[955],"number_text":"੯੫੫।","page":490,"lines":[{"gurmukhi":"ਊਧਵ ਉਤਰ ਦੇਤ ਭਯੋ ਅਤਿ ਬਿਯੋਗ ਮਨੇ ਅਪਨੇ ਸੋਊ ਕੈ ਹੈ।","roman":"Oodhav utar det bhayo ati biyog mane apne so'oo kai hai |","meaning_en":"Udhav gave answer, feeling great separation in his own heart,","page":490,"meaning_status":"draft","note":"ਅਤਿ ਬਿਯੋਗ ਮਨੇ ਅਪਨੇ ਸੋਊ ਕੈ ਹੈ: sense uncertain."},{"gurmukhi":"ਗ੍ਵਾਰਨਿ ਕੇ ਮਨ ਮਧਿ ਬਿਖੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜੋਊ ਬਾਤ ਰੁਚੈ ਹੈ।","roman":"Gvaarni ke man madhi bikhai kabi syaam kahai jo'oo baat ruchai hai |","meaning_en":"speaking, says the poet Shyam, what would please the milkmaids' hearts:","page":490,"meaning_status":"draft"},{"gurmukhi":"ਥੋਰੇ ਹੀ ਦ੍ਯੋਸਨ ਮੈ ਮਿਲਿ ਹੈ ਜਿਹ ਕੇ ਉਰ ਮੈ ਨ ਕਛੂ ਭ੍ਰਮ ਭੈ ਹੈ।","roman":"Thore hee dyosan mai mili hai jih ke ur mai na kachhoo bhram bhai hai |","meaning_en":"'He will meet you within a few days, he in whose heart there is no doubt or fear.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗਿਨ ਹੋਇ ਜਪੋ ਹਰਿ ਕੋ ਮੁਖ ਮਾਗਹੁ ਗੀ ਤੁਮ ਸੋ ਬਰੁ ਦੈ ਹੈ। ੯੫੫।","roman":"Jogin hoi japo hari ko mukh maaghu gee tum so baru dai hai | 955 |","meaning_en":"Become yoginis and repeat Hari's name; whatever you ask, he will grant you as a boon.'","page":490,"meaning_status":"draft"}]},{"type":"verse","number":[956],"number_text":"੯੫੬।","page":490,"lines":[{"gurmukhi":"ਉਨ ਦੈ ਇਮ ਊਧਵ ਗ੍ਯਾਨ ਚਲਿਯੋ ਚਲਿ ਕੈ ਜਸੁਧਾ ਪਤਿ ਪੈ ਸੋਊ ਆਯੋ।","roman":"Un dai im oodhav gyaan chaliyo chali kai jasudhaa pati pai so'oo aayo |","meaning_en":"Having given them knowledge in this way, Udhav set off and came to Yashoda's husband.","page":490,"meaning_status":"draft","note":"Yashoda's husband: Nand."},{"gurmukhi":"ਆਵਤ ਹੀ ਜਸੁਧਾ ਜਸੁਧਾ ਪਤਿ ਪਾਇਨ ਊਪਰ ਸੀਸ ਝੁਕਾਯੋ।","roman":"Aavat hee jasudhaa jasudhaa pati paain oopar sees jhukaayo |","meaning_en":"As soon as he came, he bowed his head at the feet of Yashoda and her husband.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਹੀ ਸ੍ਯਾਮ ਸਦਾ ਕਹੀਯੋ ਕਹਿ ਕੈ ਇਹ ਮੋ ਪਹਿ ਕਾਨ੍ਹ ਪਠਾਯੋ।","roman":"Syaam hee syaam sadaa kaheeyo kahi kai ih mo pahi kaanh pathaayo |","meaning_en":"'Always say \"Shyam, Shyam\"; Kanha sent me to you to say this.'","page":490,"meaning_status":"draft","note":"Speaker and sense uncertain; it may be Nand's message to Krishna through Udhav."},{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਰਥ ਪੈ ਚੜ ਕੈ ਰਥ ਕੋ ਮਥੁਰਾ ਹੀ ਕੀ ਓਰਿ ਚਲਾਯੋ। ੯੫੬।","roman":"Yau kahi kai rath pai char kai rath ko mathuraa hee kee ori chalaayo | 956 |","meaning_en":"Saying this, he mounted the chariot and drove it towards Mathura.","page":490,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਊਧਵ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","gurmukhi":"ਊਧਵ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","roman":"Oodhav baach kaanh joo so","meaning_en":"Udhav said to Krishna:","page":490,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":490,"meaning_status":"draft"},{"type":"verse","number":[957],"number_text":"੯੫੭।","page":490,"lines":[{"gurmukhi":"ਆਇ ਤਬੈ ਮਥੁਰਾ ਪੁਰ ਮੈ ਬਲਿਰਾਮ ਅਉ ਸ੍ਯਾਮ ਕੇ ਪਾਇ ਪਰਿਯੋ।","roman":"Aai tabai mathuraa pur mai baliraam au syaam ke paai pariyo |","meaning_en":"Then, coming into the city of Mathura, he fell at the feet of Balram and Shyam.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿਯੋ ਜੋ ਤੁਮ ਮੋ ਕਹਿ ਕੈ ਪਠਿਯੋ ਤਿਨ ਸੋ ਇਹ ਭਾਤਿ ਹੀ ਸੋ ਉਚਰਿਯੋ।","roman":"Kahiyo jo tum mo kahi kai pathiyo tin so ih bhaati hee so uchriyo |","meaning_en":"'What you told me and sent me for, I said to them in just that way.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗ ਨੰਦ ਕੇ ਅਉ ਉਨ ਗ੍ਵਾਰਨਿ ਕੇ ਚਰਚਾ ਕਰਿ ਗ੍ਯਾਨ ਕੀ ਫੇਰਿ ਫਿਰਿਯੋ।","roman":"Sang nand ke au un gvaarni ke charchaa kari gyaan kee pheri phiriyo |","meaning_en":"I discoursed on knowledge with Nand and with those milkmaids, and came back again.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮਰੋ ਮੁਖ ਭਾਨੁ ਨਿਹਾਰਤ ਹੀ ਤਮ ਸੋ ਦੁਖ ਥੋ ਸਭ ਦੂਰ ਕਰਿਯੋ। ੯੫੭।","roman":"Tumro mukh bhaanu nihaarat hee tam so dukh tho sabh door kariyo | 957 |","meaning_en":"As soon as I see the sun of your face, all my darkness of sorrow is driven away.'","page":490,"meaning_status":"draft","note":"Who sees the face is uncertain; read as Udhav."}]},{"type":"verse","number":[958],"number_text":"੯੫੮।","page":490,"lines":[{"gurmukhi":"ਤੁਮਰੇ ਪਗ ਭੇਟਿ ਗਯੋ ਜਬ ਹੀ ਤਬ ਹੀ ਫੁਨਿ ਨੰਦ ਕੇ ਧਾਮਿ ਗਯੋ।","roman":"Tumre pag bheti gayo jab hee tab hee phuni nand ke dhaami gayo |","meaning_en":"'As soon as I had touched your feet, I went on to Nand's house.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਕੋ ਕਰਿ ਕੈ ਹਰਿ ਗ੍ਯਾਨ ਪ੍ਰਬੋਧ ਉਠਿਯੋ ਚਲਿ ਗ੍ਵਾਰਨਿ ਪਾਸ ਅਯੋ।","roman":"Tih ko kari kai hari gyaan prabodh uthiyo chali gvaarni paas ayo |","meaning_en":"Having instructed him in the knowledge of Hari, I rose and went to the milkmaids.","page":490,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮਰੋ ਉਨ ਦੁਖ ਕਹਿਯੋ ਹਮ ਪੈ ਸੁਨਿ ਉਤਰ ਮੈ ਇਹ ਭਾਤਿ ਦਯੋ।","roman":"Tumro un dukh kahiyo ham pai suni utar mai ih bhaati dayo |","meaning_en":"They told me of their pain over you; hearing it, I gave this answer:","page":490,"meaning_status":"draft"},{"gurmukhi":"ਬਲਿ ਸ੍ਯਾਮਹਿ ਸ੍ਯਾਮ ਸਦਾ ਜਪੀਯੋ ਸੁਨਿ ਨਾਮਹਿ ਪ੍ਰੇਮ ਘਨੋ ਬਢਯੋ। ੯੫੮।","roman":"Bali syaamhi syaam sadaa japeeyo suni naamhi prem ghano badhyo | 958 |","meaning_en":"\"Always repeat 'Shyam, Shyam'\"; hearing the name, their love grew greatly.'","page":490,"meaning_status":"draft","note":"ਬਲਿ: read as an exclamation of devotion ('I am a sacrifice') or as 'mighty'; left untranslated in the line; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਊਧਵ ਸੰਦੇਸ ਬਾਚ","gurmukhi":"ਊਧਵ ਸੰਦੇਸ ਬਾਚ","roman":"Oodhav sandes baach","meaning_en":"Udhav gave the message:","page":490,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":490,"meaning_status":"draft"},{"type":"verse","number":[959],"number_text":"੯੫੯।","page":490,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਨਿ ਮੋ ਸੰਗ ਐਸੇ ਕਹਿਯੋ ਹਮ ਓਰ ਤੇ ਸ੍ਯਾਮ ਕੇ ਪਾਇਨ ਪਇਯੈ।","roman":"Gvaarni mo sang aise kahiyo ham or te syaam ke paain paiyai |","meaning_en":"'The milkmaids said this to me: \"Fall at Shyam's feet on our behalf,","page":490,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹੀਯੋ ਪੁਰ ਬਾਸਿਨ ਕੋ ਤਜਿ ਕੈ ਬ੍ਰਿਜ ਬਾਸਿਨ ਕੋ ਸੁਖੁ ਦਇਯੈ।","roman":"Yau kaheeyo pur baasin ko taji kai brij baasin ko sukhu daiyai |","meaning_en":"and say this: leave the city women and give happiness to the people of Braj.\"","page":490,"meaning_status":"draft"},{"gurmukhi":"ਜਸੁਧਾ ਇਹ ਭਾਤਿ ਕਰੀ ਬਿਨਤੀ ਬਿਨਤੀ ਕਹੀਯੋ ਸੰਗਿ ਪੂਤ ਕਨਇਯੈ।","roman":"Jasudhaa ih bhaati karee bintee bintee kaheeyo sangi poot kanaiyai |","meaning_en":"Yashoda made this plea: \"Put this plea to my son Kanhaiya;","page":490,"meaning_status":"draft"},{"gurmukhi":"ਊਧਵ ਤਾ ਸੰਗ ਯੌ ਕਹੀਯੌ ਬਹੁਰੋ ਫਿਰਿ ਆਇ ਕੈ ਮਾਖਨ ਖਇਯੈ। ੯੫੯।","roman":"Oodhav taa sang yau kaheeyau bahuro phiri aai kai maakhan khaiyai | 959 |","meaning_en":"Udhav, say this to him: come back again and eat butter.\"'","page":490,"meaning_status":"draft"}]},{"type":"verse","number":[960],"number_text":"੯੬੦।","page":491,"lines":[{"gurmukhi":"ਅਉਰ ਕਹੀ ਬਿਨਤੀ ਤੁਮ ਪੈ ਸੁ ਸੁਨੋ ਅਰੁ ਅਉਰਨ ਬਾਤਨ ਡਾਰੋ।","roman":"Aur kahee bintee tum pai su suno aru auran baatan daaro |","meaning_en":"'And she made another plea to you; hear it, and set other matters aside.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਐਸੇ ਕਹਾ ਜਸੁਧਾ ਤੁਮ ਕੋ ਹਮ ਕੋ ਅਤਿ ਹੀ ਬ੍ਰਿਜਨਾਥ ਪਿਆਰੋ।","roman":"Aise kahaa jasudhaa tum ko ham ko ati hee brijnaath piaaro |","meaning_en":"Yashoda said this to you: \"The Lord of Braj is very dear to me.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਕਰੋ ਨ ਕਛੂ ਗਨਤੀ ਹਮਰੋ ਸੁ ਕਹਿਯੋ ਤੁਮ ਪ੍ਰੇਮ ਬਿਚਾਰੋ।","roman":"Taa te karo na kachhoo gantee hamro su kahiyo tum prem bichaaro |","meaning_en":"So weigh nothing else; think of my love, I say,","page":491,"meaning_status":"draft","note":"ਕਰੋ ਨ ਕਛੂ ਗਨਤੀ: 'make no reckoning'; sense uncertain."},{"gurmukhi":"ਤਾਹੀ ਤੇ ਬੇਗ ਤਜੋ ਮਥੁਰਾ ਉਠ ਕੈ ਅਬ ਹੀ ਬ੍ਰਿਜ ਪੂਤ ਪਧਾਰੋ। ੯੬੦।","roman":"Taahee te beg tajo mathuraa uth kai ab hee brij poot padhaaro | 960 |","meaning_en":"and so leave Mathura quickly; rise now, son, and come to Braj.\"'","page":491,"meaning_status":"draft"}]},{"type":"verse","number":[961],"number_text":"੯੬੧।","page":491,"lines":[{"gurmukhi":"ਮਾਤ ਕਰੀ ਬਿਨਤੀ ਤੁਮ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜੋਊ ਹੈ ਬ੍ਰਿਜਰਾਨੀ।","roman":"Maat karee bintee tum pai kabi syaam kahai jo'oo hai brijraanee |","meaning_en":"'Your mother, the queen of Braj, says the poet Shyam, made a plea to you.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹੀ ਕੋ ਪ੍ਰੇਮ ਘਨੋ ਤੁਮ ਸੋ ਹਮ ਆਪਨੇ ਜੀ ਮਹਿ ਪ੍ਰੀਤਿ ਪਛਾਨੀ।","roman":"Taahee ko prem ghano tum so ham aapne jee mahi preeti pachhaanee |","meaning_en":"Her love for you is deep; I recognised that love in my own heart.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਕਹਿਓ ਤਜਿ ਕੈ ਮਥੁਰਾ ਬ੍ਰਿਜ ਆਵਹੁ ਯਾ ਬਿਧਿ ਬਾਤ ਬਖਾਨੀ।","roman":"Taa te kahio taji kai mathuraa brij aavhu yaa bidhi baat bakhaanee |","meaning_en":"So she said, \"Leave Mathura and come to Braj\"; in this way she spoke:","page":491,"meaning_status":"draft"},{"gurmukhi":"ਇਯਾਨੇ ਹੁਤੇ ਤਬ ਮਾਨਤ ਥੇ ਅਬ ਸਯਾਨੇ ਭਏ ਤਬ ਏਕ ਨ ਮਾਨੀ। ੯੬੧।","roman":"Iyaane hute tab maanat the ab sayaane bhae tab ek na maanee | 961 |","meaning_en":"\"When you were little you obeyed me; now that you have grown wise, you obey not a word.\"'","page":491,"meaning_status":"draft"}]},{"type":"verse","number":[962],"number_text":"੯੬੨।","page":491,"lines":[{"gurmukhi":"ਤਾਹੀ ਤੇ ਸੰਗਿ ਕਹੋ ਤੁਮਰੇ ਤਜਿ ਕੈ ਮਥਰਾ ਬ੍ਰਿਜ ਕੋ ਅਬ ਅਈਯੈ।","roman":"Taahee te sangi kaho tumre taji kai mathraa brij ko ab aeeyai |","meaning_en":"'Therefore I tell you: leave Mathura and come to Braj now.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨ ਕੈ ਸੀਖ ਕਹੋ ਹਮਰੀ ਤਿਹ ਠਉਰ ਨਹੀ ਪਲਵਾ ਠਹਰਈਯੈ।","roman":"Maan kai seekh kaho hamree tih thaur nahee palvaa thahraeeyai |","meaning_en":"Heed my advice, I say: do not stay in that place even a moment.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿ ਗ੍ਵਾਰਨੀਯਾ ਹਮ ਸੋ ਸਭ ਹੀ ਬ੍ਰਿਜ ਬਾਸਿਨ ਕੋ ਸੁਖ ਦਈਯੈ।","roman":"Yau kahi gvaarneeyaa ham so sabh hee brij baasin ko sukh daeeyai |","meaning_en":"\"Thus,\" the milkmaids said to me, \"give happiness to all the people of Braj.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਸੁਧਿ ਭੂਲ ਗਈ ਤੁਮ ਕੋ ਹਮਰੈ ਜਿਹ ਅਉਸਰ ਪਾਇਨ ਪਈਯੈ। ੯੬੨।","roman":"So sudhi bhool gaee tum ko hamrai jih ausar paain paeeyai | 962 |","meaning_en":"You have forgotten the time when you fell at our feet.\"'","page":491,"meaning_status":"draft","note":"Who fell at whose feet is uncertain."}]},{"type":"verse","number":[963],"number_text":"੯੬੩।","page":491,"lines":[{"gurmukhi":"ਤਾਹੀ ਤੇ ਤ੍ਯਾਗਿ ਰਹਿਯੋ ਮਥੁਰਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬ੍ਰਿਜ ਮੈ ਫਿਰਿ ਆਵਹੁ।","roman":"Taahee te tyaagi rahiyo mathuraa kabi syaam kahai brij mai phiri aavhu |","meaning_en":"'So leave Mathura, says the poet Shyam, and come back into Braj.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਵਾਰਨਿ ਪ੍ਰੀਤਿ ਪਛਾਨ ਕਹਿਯੋ ਤਿਹ ਤੇ ਤਿਹ ਠਉਰ ਨ ਢੀਲ ਲਗਾਵਹੁ।","roman":"Gvaarni preeti pachhaan kahiyo tih te tih thaur na dheel lagaavhu |","meaning_en":"Recognising the milkmaids' love, I say: make no delay in that place.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿ ਪਾਇਨ ਪੈ ਹਮਰੇ ਹਮ ਸੰਗ ਕਹਿਯੋ ਸੁ ਤਹਾ ਤੁਮ ਜਾਵਹੁ।","roman":"Yau kahi paain pai hamre ham sang kahiyo su tahaa tum jaavhu |","meaning_en":"Saying this, they fell at my feet and told me, \"You go there,","page":491,"meaning_status":"draft"},{"gurmukhi":"ਜਾਇ ਕੈ ਆਵਹੁ ਯੌ ਕਹੀਯੋ ਹਮ ਕੋ ਸੁਖ ਹੋ ਤੁਮ ਹੂੰ ਸੁਖ ਪਾਵਹੁ। ੯੬੩।","roman":"Jaai kai aavhu yau kaheeyo ham ko sukh ho tum hoon sukh paavhu | 963 |","meaning_en":"go and tell him thus, 'Come'; we shall be happy, and you too will find happiness.\"'","page":491,"meaning_status":"draft"}]},{"type":"verse","number":[964],"number_text":"੯੬੪।","page":491,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਕਹਿਯੋ ਤਜ ਕੈ ਮਥੁਰਾ ਫਿਰਿ ਕੈ ਬ੍ਰਿਜ ਬਾਸਿਨ ਕੋ ਸੁਖ ਦੀਜੈ।","roman":"Taa te kahiyo taj kai mathuraa phiri kai brij baasin ko sukh deejai |","meaning_en":"'So they said: leave Mathura, come back and give happiness to the people of Braj.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਆਵਹੁ ਫੇਰਿ ਕਹਿਯੋ ਬ੍ਰਿਜ ਮੈ ਇਹ ਕਾਮ ਕੀਏ ਤੁਮਰੋ ਨਹੀ ਛੀਜੈ।","roman":"Aavhu pheri kahiyo brij mai ih kaam kee'e tumro nahee chheejai |","meaning_en":"Come back to Braj, they said; by doing this nothing of yours is lost.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਆਇ ਕ੍ਰਿਪਾਲ ਦਿਖਾਵਹੁ ਰੂਪ ਕਹਿਯੋ ਜਿਹ ਦੇਖਤ ਹੀ ਮਨ ਜੀਜੈ।","roman":"Aai kripaal dikhaavhu roop kahiyo jih dekhat hee man jeejai |","meaning_en":"Come, merciful one, show your form, they said, at the sight of which the heart lives.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਕੁੰਜ ਗਲੀਨ ਮੋ ਫੇਰਿ ਕਹਿਯੋ ਹਮਰੇ ਅਧਰਾਨਨ ਕੋ ਰਸ ਲੀਜੈ। ੯੬੪।","roman":"Kunj galeen mo pheri kahiyo hamre adhraanan ko ras leejai | 964 |","meaning_en":"In the lanes of the groves, they said, once more taste the nectar of our lips.'","page":491,"meaning_status":"draft"}]},{"type":"verse","number":[965],"number_text":"੯੬੫।","page":491,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕਹਿਯੋ ਸੰਗ ਹੈ ਤੁਮਰੇ ਜੁ ਹੁਤੀ ਤੁਮ ਕੋ ਬ੍ਰਿਜ ਬੀਚ ਪ੍ਯਾਰੀ।","roman":"Syaam kahiyo sang hai tumre ju hutee tum ko brij beech pyaaree |","meaning_en":"'Shyam, she who was dear to you in Braj spoke to you thus:","page":491,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹ ਰਚੇ ਪੁਰ ਬਾਸਿਨ ਸੋ ਕਬਹੂੰ ਨ ਹੀਏ ਬ੍ਰਿਜ ਨਾਰਿ ਚਿਤਾਰੀ।","roman":"Kaanh rache pur baasin so kabhoon na hee'e brij naari chitaaree |","meaning_en":"\"Krishna is absorbed with the city women, and never remembers the women of Braj in his heart.\"","page":491,"meaning_status":"draft"},{"gurmukhi":"ਪੰਥ ਨਿਹਾਰਤ ਨੈਨਨ ਕੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਪੁਤਰੀ ਦੋਊ ਹਾਰੀ।","roman":"Panth nihaarat nainan kee kabi syaam kahai putree do'oo haaree |","meaning_en":"Watching the road, says the poet Shyam, both pupils of their eyes are worn out.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਊਧਵ ਸ੍ਯਾਮ ਸੋ ਯੌ ਕਹੀਯੋ ਤੁਮਰੇ ਬਿਨੁ ਭੀ ਸਭ ਗ੍ਵਾਰਿ ਬਿਚਾਰੀ। ੯੬੫।","roman":"Oodhav syaam so yau kaheeyo tumre binu bhee sabh gvaari bichaaree | 965 |","meaning_en":"\"Udhav, say this to Shyam: without you all the milkmaids have become wretched.\"'","page":491,"meaning_status":"draft"}]},{"type":"verse","number":[966],"number_text":"੯੬੬।","page":491,"lines":[{"gurmukhi":"ਅਉਰ ਕਹੀ ਤੁਮ ਸੋ ਹਰਿ ਜੂ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਤੁਮ ਕੋ ਜੋਊ ਪ੍ਯਾਰੀ।","roman":"Aur kahee tum so hari joo brikhbhaan sutaa tum ko jo'oo pyaaree |","meaning_en":"'And, Hari, Brikhbhan's daughter, who is dear to you, said this to you:","page":491,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਦਿਨ ਤੇ ਬ੍ਰਿਜ ਤ੍ਯਾਗ ਗਏ ਦਿਨ ਤਾ ਕੀ ਨਹੀ ਹਮ ਹੂੰ ਹੈ ਸੰਭਾਰੀ।","roman":"Jaa din te brij tyaag gae din taa kee nahee ham hoon hai sanbhaaree |","meaning_en":"\"Since the day you left Braj, I have not been able to hold myself together.","page":491,"meaning_status":"draft","note":"ਹਮ ਹੂੰ ਹੈ ਸੰਭਾਰੀ: sense uncertain."},{"gurmukhi":"ਆਵਹੁ ਤ੍ਯਾਗਿ ਅਬੈ ਮਥੁਰਾ ਤੁਮਰੇ ਬਿਨੁ ਗੀ ਅਬ ਹੋਇ ਬਿਚਾਰੀ।","roman":"Aavhu tyaagi abai mathuraa tumre binu gee ab hoi bichaaree |","meaning_en":"Leave Mathura and come now; without you I have become wretched.","page":491,"meaning_status":"draft"},{"gurmukhi":"ਮੈ ਤੁਮ ਸਿਉ ਹਰਿ ਮਾਨ ਕਰਿਯੋ ਤਜਿ ਆਵਹੁ ਮਾਨ ਅਬੈ ਹਮ ਹਾਰੀ। ੯੬੬।","roman":"Mai tum siu hari maan kariyo taji aavhu maan abai ham haaree | 966 |","meaning_en":"Hari, I sulked with you; leave your pride and come now; I own myself beaten.","page":491,"meaning_status":"draft"}]},{"type":"verse","number":[967],"number_text":"੯੬੭।","page":492,"lines":[{"gurmukhi":"ਤ੍ਯਾਗ ਗਏ ਹਮ ਕੋ ਕਿਹ ਹੇਤ ਤੇ ਬਾਤ ਕਛੂ ਤੁਮਰੀ ਨ ਬਿਗਾਰੀ।","roman":"Tyaag gae ham ko kih het te baat kachhoo tumree na bigaaree |","meaning_en":"For what reason did you leave us? I spoiled nothing of yours.\"","page":492,"meaning_status":"draft"},{"gurmukhi":"ਪਾਇਨ ਮੋ ਪਰ ਕੈ ਸੁਨੀਯੈ ਪ੍ਰਭ ਏ ਬਤੀਯਾ ਇਹ ਭਾਤਿ ਉਚਾਰੀ।","roman":"Paain mo par kai suneeyai prabh e bateeyaa ih bhaati uchaaree |","meaning_en":"\"Falling at your feet, Lord, hear me\": she spoke these words thus:","page":492,"meaning_status":"draft"},{"gurmukhi":"ਆਪ ਰਚੇ ਪੁਰ ਬਾਸਿਨ ਸੋ ਮਨ ਤੇ ਸਬ ਹੀ ਬ੍ਰਿਜਨਾਰ ਬਿਸਾਰੀ।","roman":"Aap rache pur baasin so man te sab hee brijnaar bisaaree |","meaning_en":"\"You yourself are absorbed with the city women and have put all the women of Braj out of mind.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨ ਕਰਿਯੋ ਤੁਮ ਸੋ ਘਟ ਕਾਮ ਕਰਿਯੋ ਅਬ ਸ੍ਯਾਮ ਹਹਾ ਹਮ ਹਾਰੀ। ੯੬੭।","roman":"Maan kariyo tum so ghat kaam kariyo ab syaam hahaa ham haaree | 967 |","meaning_en":"I sulked with you and did a mean thing; now, Shyam, alas, I own myself beaten.\"'","page":492,"meaning_status":"draft"}]},{"type":"verse","number":[968],"number_text":"੯੬੮।","page":492,"lines":[{"gurmukhi":"ਅਉਰ ਕਰੀ ਤੁਮ ਸੋ ਬਿਨਤੀ ਸੋਊ ਸ੍ਯਾਮ ਕਹੈ ਚਿਤ ਦੈ ਸੁਨਿ ਲੀਜੈ।","roman":"Aur karee tum so bintee so'oo syaam kahai chit dai suni leejai |","meaning_en":"'She made another plea to you, says Shyam; listen to it attentively:","page":492,"meaning_status":"draft"},{"gurmukhi":"ਖੇਲਤ ਥੀ ਤੁਮ ਸੋ ਬਨ ਮੈ ਤਿਹ ਅਉਸਰ ਕੀ ਕਬਹੂੰ ਸੁਧਿ ਕੀਜੈ।","roman":"Khelat thee tum so ban mai tih ausar kee kabhoon sudhi keejai |","meaning_en":"\"We used to play with you in the forest; remember that time some day.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਥੀ ਤੁਮ ਪੈ ਮਿਲ ਕੈ ਜਿਹ ਕੀ ਸੁਰ ਤੇ ਕਛੁ ਤਾਨ ਨ ਛੀਜੈ।","roman":"Gaavat thee tum pai mil kai jih kee sur te kachhu taan na chheejai |","meaning_en":"We used to sing together with you, and from your voice not a note fell short.\"","page":492,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੋ ਕਹਿਯੋ ਤਿਹ ਕੀ ਸੁਧਿ ਕੈ ਬਹੁਰੋ ਬ੍ਰਿਜ ਬਾਸਿਨ ਕੋ ਸੁਖ ਦੀਜੈ। ੯੬੮।","roman":"Taa ko kahiyo tih kee sudhi kai bahuro brij baasin ko sukh deejai | 968 |","meaning_en":"Remembering that, she said, come back and give happiness to the people of Braj.'","page":492,"meaning_status":"draft"}]},{"type":"verse","number":[969],"number_text":"੯੬੯।","page":492,"lines":[{"gurmukhi":"ਅਉਰ ਕਹੀ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਹਰਿ ਜੂ ਸੋਊ ਬਾਤ ਅਬੈ ਸੁਨਿ ਲਈਯੈ।","roman":"Aur kahee brikhbhaan sutaa hari joo so'oo baat abai suni laeeyai |","meaning_en":"'And, Hari, Brikhbhan's daughter said something more; hear that now.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਕਹਿਯੋ ਤ੍ਯਾਗ ਤੁਮੈ ਮਥੁਰਾ ਬਹੁਰੇ ਬ੍ਰਿਜ ਕੁੰਜਨ ਭੀਤਰ ਅਈਯੈ।","roman":"Yau kahiyo tyaag tumai mathuraa bahure brij kunjan bheetar aeeyai |","meaning_en":"She said thus: \"Leave Mathura and come back into the groves of Braj.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਹਮਰੇ ਸੰਗਿ ਖੇਲਤ ਥੇ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਫਿਰਿ ਖੇਲ ਮਚਈਯੈ।","roman":"Jiu hamre sangi khelat the ih bhaati kahiyo phiri khel machaeeyai |","meaning_en":"As you used to play with us,\" she said, \"in the same way set up the play again.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਚਾਹ ਘਨੀ ਤੁਹਿ ਦੇਖਨ ਕੀ ਗ੍ਰਿਹ ਆਇ ਕਹਿਯੋ ਹਮ ਕੋ ਸੁਖ ਦਈਯੈ। ੯੬੯।","roman":"Chaah ghanee tuhi dekhan kee grih aai kahiyo ham ko sukh daeeyai | 969 |","meaning_en":"I long greatly to see you; come home,\" she said, \"and give us happiness.\"'","page":492,"meaning_status":"draft"}]},{"type":"verse","number":[970],"number_text":"੯੭੦।","page":492,"lines":[{"gurmukhi":"ਤੇਰੇ ਪਿਖੇ ਬਿਨੁ ਹੇ ਹਰਿ ਜੀ ਕਿਹੀ ਭਾਤਿ ਕਹਿਯੋ ਨਹੀ ਮੋ ਮਨ ਭੀਜੈ।","roman":"Tere pikhe binu he hari jee kihee bhaati kahiyo nahee mo man bheejai |","meaning_en":"'\"O Hari, without seeing you, in no way is my heart content,\" she said.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਸੂਕਿ ਭਈ ਪੁਤਰੀ ਸੀ ਕਹਿਯੋ ਕਹੀ ਯੌ ਹਰਿਸੋ ਬਿਨਤੀ ਸੁਨ ਲੀਜੈ।","roman":"Sooki bhaee putree see kahiyo kahee yau hariso bintee sun leejai |","meaning_en":"She has dried up like a doll, she said; she spoke thus: \"Hari, hear my plea.","page":492,"meaning_status":"draft","note":"ਪੁਤਰੀ: 'doll' or 'puppet'; sense uncertain."},{"gurmukhi":"ਬਾਤਨ ਮੋਹਿ ਨ ਹੋਤ ਪ੍ਰਤੀਤਿ ਕਹਿਯੋ ਘਨ ਸ੍ਯਾਮ ਪਿਖੇਈ ਪ੍ਰਸੀਜੈ।","roman":"Baatan mohi na hot prateeti kahiyo ghan syaam pikhe'ee praseejai |","meaning_en":"I put no faith in words,\" she said; \"only seeing the cloud-dark Shyam will satisfy me.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਆਨਨ ਮੈ ਸਮ ਚੰਦ ਨਿਹਾਰਿ ਚਕੋਰ ਸੀ ਗ੍ਵਾਰਨਿ ਕੋ ਸੁਖ ਦੀਜੈ। ੯੭੦।","roman":"Aanan mai sam chand nihaari chakor see gvaarni ko sukh deejai | 970 |","meaning_en":"Let the milkmaids, like chakor birds, gaze on your moon-like face; give them joy.\"'","page":492,"meaning_status":"draft","note":"Chakor: a bird said to gaze on the moon."}]},{"type":"heading","kind":"speaker","name":"ਊਧਵ ਚੰਦ੍ਰਭਗਾ ਕੋ ਸੰਦੇਸ ਬਾਚ","gurmukhi":"ਊਧਵ ਚੰਦ੍ਰਭਗਾ ਕੋ ਸੰਦੇਸ ਬਾਚ","roman":"Oodhav chandrabhgaa ko sandes baach","meaning_en":"Udhav gave Chandarbhaga's message:","page":492,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":492,"meaning_status":"draft"},{"type":"verse","number":[971],"number_text":"੯੭੧।","page":492,"lines":[{"gurmukhi":"ਯੌ ਤੁਮ ਸੋ ਕਹਿਯੋ ਚੰਦ੍ਰਭਗਾ ਹਰਿ ਜੂ ਅਪਨੋ ਮੁਖ ਚੰਦ ਦਿਖਈਯੈ।","roman":"Yau tum so kahiyo chandrabhgaa hari joo apno mukh chand dikhaeeyai |","meaning_en":"'Chandarbhaga said this to you: \"Hari, show us your moon-like face.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਯਾਕੁਲ ਹੋਇ ਗਈ ਬਿਨੁ ਤ੍ਵੈ ਸੁ ਹਹਾ ਕਹਿਯੋ ਟੇਰਿ ਹਲੀਧਰ ਭਈਯੈ।","roman":"Byaakul hoi gaee binu tvai su hahaa kahiyo teri haleedhar bhaeeyai |","meaning_en":"Without you I have become distraught\"; \"Alas!\" she cried, \"O brother of the plough-bearer!","page":492,"meaning_status":"draft","note":"ਹਲੀਧਰ ਭਈਯੈ: brother of Balram, i.e. Krishna."},{"gurmukhi":"ਤਾਹੀ ਤੇ ਆਵਹੁ ਨ ਚਿਰ ਲਾਵਹੁ ਮੋ ਜੀਯ ਕੀ ਜਬ ਹੀ ਸੁਨ ਲਈਯੈ।","roman":"Taahee te aavhu na chir laavhu mo jeey kee jab hee sun laeeyai |","meaning_en":"So come, do not delay, as soon as you have heard the state of my heart.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਹੇ ਬ੍ਰਿਜਨਾਥ ਕਹਿਯੋ ਨੰਦ ਲਾਲ ਚਕੋਰਨ ਗ੍ਵਾਰਨਿ ਕੋ ਸੁਖ ਦਈਯੈ। ੯੭੧।","roman":"He brijnaath kahiyo nand laal chakoran gvaarni ko sukh daeeyai | 971 |","meaning_en":"O Lord of Braj,\" she said, \"Nand's darling, give joy to the chakor-like milkmaids.\"'","page":492,"meaning_status":"draft"}]},{"type":"verse","number":[972],"number_text":"੯੭੨।","page":492,"lines":[{"gurmukhi":"ਹੇ ਬ੍ਰਿਜ ਨਾਥ ਕਹਿਯੋ ਬ੍ਰਿਜ ਨਾਰਿ ਹਹਾ ਨੰਦ ਲਾਲ ਨਹੀ ਚਿਰ ਕੀਜੈ।","roman":"He brij naath kahiyo brij naari hahaa nand laal nahee chir keejai |","meaning_en":"'\"O Lord of Braj,\" said the woman of Braj, \"alas, Nand's darling, do not delay.","page":492,"meaning_status":"draft"},{"gurmukhi":"ਹੇ ਜਦੁਰਾ ਅਗ੍ਰਜ ਜਸੁਧਾ ਸੁਤ ਰਛੁਕ ਧੇਨੁ ਕਹਿਯੋ ਸੁਨ ਲੀਜੈ।","roman":"He jaduraa agraj jasudhaa sut rachhuk dhenu kahiyo sun leejai |","meaning_en":"O king of the Yadavs, foremost one, son of Yashoda, protector of cows,\" she said, \"listen.","page":492,"meaning_status":"draft","note":"ਅਗ੍ਰਜ: 'first-born/foremost'; uncertain."},{"gurmukhi":"ਸਾਪ ਕੇ ਨਾਥ ਅਸੁਰ ਬਧੀਯਾ ਅਰੁ ਆਵਨ ਗੋਕੁਲ ਨਾਥ ਨ ਛੀਜੈ।","roman":"Saap ke naath asur badheeyaa aru aavan gokul naath na chheejai |","meaning_en":"Master of the serpent, slayer of demons, Lord of Gokul, do not fail to come.","page":492,"meaning_status":"draft","note":"ਸਾਪ ਕੇ ਨਾਥ: read as 'subduer of the serpent' (Kali); uncertain."},{"gurmukhi":"ਕੰਸ ਬਿਦਾਰ ਅਬੈ ਕਰਤਾਰ ਚਕੋਰਨ ਗਾਰਨਿ ਕੋ ਸੁਖ ਦੀਜੈ। ੯੭੨।","roman":"Kans bidaar abai kartaar chakoran gaarni ko sukh deejai | 972 |","meaning_en":"Destroyer of Kans, Creator, now give joy to the chakor-like milkmaids.\"'","page":492,"meaning_status":"draft","note":"ਗਾਰਨਿ: printed so; read as ਗ੍ਵਾਰਨਿ 'milkmaids'."}]},{"type":"verse","number":[973],"number_text":"੯੭੩।","page":493,"lines":[{"gurmukhi":"ਹੇ ਨੰਦ ਨੰਦ ਕਹਿਯੋ ਸੁਖ ਕੰਦ ਮੁਕੰਦ ਸੁਨੋ ਬਤੀਯਾ ਗਿਰਧਾਰੀ।","roman":"He nand nand kahiyo sukh kand mukand suno bateeyaa girdhaaree |","meaning_en":"'\"O son of Nand,\" she said, \"source of joy, Mukand, hear my words, holder of the mountain.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਗੋਕੁਲ ਨਾਥ ਕਹੋ ਬਕ ਕੇ ਰਿਪੁ ਰੂਪ ਦਿਖਾਵਹੁ ਮੋਹਿ ਮੁਰਾਰੀ।","roman":"Gokul naath kaho bak ke ripu roop dikhaavhu mohi muraaree |","meaning_en":"Lord of Gokul, I say, enemy of Bak, Murari, show me your form.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ ਸੁਨੋ ਜਸੁਧਾ ਸੁਤ ਭੀ ਬਿਨੁ ਤ੍ਵੈ ਬ੍ਰਿਜ ਨਾਰਿ ਬਿਚਾਰੀ।","roman":"Sree brijnaath suno jasudhaa sut bhee binu tvai brij naari bichaaree |","meaning_en":"Sri Lord of Braj, listen, son of Yashoda: without you the women of Braj are wretched.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨਤ ਹੈ ਹਰਿ ਜੂ ਅਪਨੇ ਮਨ ਤੇ ਸਭ ਹੀ ਇਹ ਤ੍ਰੀਯ ਬਿਸਾਰੀ। ੯੭੩।","roman":"Jaanat hai hari joo apne man te sabh hee ih treey bisaaree | 973 |","meaning_en":"We know, Hari, that you have put all these women out of your mind.\"'","page":493,"meaning_status":"draft"}]},{"type":"verse","number":[974],"number_text":"੯੭੪।","page":493,"lines":[{"gurmukhi":"ਕੰਸ ਕੇ ਮਾਰ ਸੁਨੋ ਕਰਤਾਰ ਬਕਾ ਮੁਖ ਫਾਰ ਕਹਿਯੋ ਸੁਨਿ ਲੈ।","roman":"Kans ke maar suno kartaar bakaa mukh phaar kahiyo suni lai |","meaning_en":"'\"Slayer of Kans, Creator, listen; you who tore open Bak's mouth,\" she said, \"listen;","page":493,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਦੋਖ ਨਿਵਾਰ ਸੁਨੋ ਬ੍ਰਿਜਨਾਥ ਅਬੈ ਇਨ ਗ੍ਵਾਰਨਿ ਰੂਪ ਦਿਖੈ।","roman":"Sabh dokh nivaar suno brijnaath abai in gvaarni roop dikhai |","meaning_en":"remover of all faults, listen, Lord of Braj: show your form now to these milkmaids.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਘਨ ਸ੍ਯਾਮ ਕੀ ਮੂਰਤਿ ਪੇਖੇ ਬਿਨਾ ਨ ਕਛੂ ਇਨ ਕੇ ਮਨ ਬੀਚ ਰੁਚੈ।","roman":"Ghan syaam kee moorti pekhe binaa na kachhoo in ke man beech ruchai |","meaning_en":"Without seeing the image of the cloud-dark Shyam, nothing pleases their hearts.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਤੇ ਹਰਿ ਜੂ ਤਜ ਕੈ ਮਥੁਰਾ ਇਨ ਕੈ ਸਭ ਸੋਕਨ ਕੋ ਹਰਿ ਦੈ। ੯੭੪।","roman":"Tih te hari joo taj kai mathuraa in kai sabh sokan ko hari dai | 974 |","meaning_en":"So, Hari, leave Mathura and take away all their sorrows.\"'","page":493,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਬਿਜੁਛਟਾ ਅਰੁ ਮੈਨਪ੍ਰਭਾ ਸੰਦੇਸ ਬਾਚ","gurmukhi":"ਬਿਜੁਛਟਾ ਅਰੁ ਮੈਨਪ੍ਰਭਾ ਸੰਦੇਸ ਬਾਚ","roman":"Bijuchhtaa aru mainprabhaa sandes baach","meaning_en":"The message of Bijchhata and Mainprabha:","page":493,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":493,"meaning_status":"draft"},{"type":"verse","number":[975],"number_text":"੯੭੫।","page":493,"lines":[{"gurmukhi":"ਬਿਜੁਛਟਾ ਅਰੁ ਮੈਨਪ੍ਰਭਾ ਸੰਗ ਤੋਹਿ ਸ੍ਯਾਮ ਕਹਿਯੋ ਸੁਨਿ ਐਸੇ।","roman":"Bijuchhtaa aru mainprabhaa sang tohi syaam kahiyo suni aise |","meaning_en":"'Shyam, listen: Bijchhata and Mainprabha spoke thus to you:","page":493,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੀਤਿ ਬਢਾਇ ਇਤੀ ਇਨ ਸੋ ਅਬ ਤ੍ਯਾਗ ਗਏ ਕਹੁ ਕਾਰਨ ਕੈਸੇ।","roman":"Preeti badhaai itee in so ab tyaag gae kahu kaaran kaise |","meaning_en":"\"Having made your love for these women grow so much, for what reason have you now left them?","page":493,"meaning_status":"draft"},{"gurmukhi":"ਆਵਹੁ ਸ੍ਯਾਮ ਨ ਢੀਲ ਲਗਾਵਹੁ ਖੇਲ ਕਰੋ ਹਮ ਸੋ ਫੁਨਿ ਵੈਸੇ।","roman":"Aavhu syaam na dheel lagaavhu khel karo ham so phuni vaise |","meaning_en":"Come, Shyam, do not delay; play with us once more as before.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨ ਕਰੈ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਪਠਵੋ ਹਮ ਕੋ ਤੁਮ ਵਾ ਬਿਧਿ ਜੈਸੇ। ੯੭੫।","roman":"Maan karai brikhbhaan sutaa pathvo ham ko tum vaa bidhi jaise | 975 |","meaning_en":"If Brikhbhan's daughter sulks, send us to her just as you did then.\"'","page":493,"meaning_status":"draft","note":"Sense uncertain."}]},{"type":"verse","number":[976],"number_text":"੯੭੬।","page":493,"lines":[{"gurmukhi":"ਊਧਵ ਸ੍ਯਾਮ ਸੋ ਯੌ ਕਹਿਯੋ ਤੁਮਰੋ ਰਹਿਬੋ ਜਬ ਸ੍ਰਉਨ ਧਰੈਗੀ।","roman":"Oodhav syaam so yau kahiyo tumro rahibo jab sraun dharaigee |","meaning_en":"'\"Udhav, say this to Shyam: when she hears that you are staying on there,","page":493,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗ ਤਬੈ ਅਪੁਨੇ ਸੁਖ ਕੋ ਅਤਿ ਹੀ ਮਨ ਭੀਤਰ ਸੋਕ ਕਰੈਗੀ।","roman":"Tyaag tabai apune sukh ko ati hee man bheetar sok karaigee |","meaning_en":"she will give up her own happiness and grieve greatly in her heart.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗਿਨ ਬਸਤ੍ਰਨ ਕੋ ਧਰਹੈ ਕਹਿਯੋ ਬਿਖ ਖਾਇ ਕੈ ਪ੍ਰਾਨ ਪਰੈਗੀ।","roman":"Jogin bastran ko dharhai kahiyo bikh khaai kai praan paraigee |","meaning_en":"She will put on a yogini's clothes, they said, or take poison and give up her life.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹੀ ਤੇ ਹੇ ਹਰਿ ਜੂ ਤੁਮ ਸੋ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਫਿਰਿ ਮਾਨ ਕਰੈਗੀ। ੯੭੬।","roman":"Taahee te he hari joo tum so brikhbhaan sutaa phiri maan karaigee | 976 |","meaning_en":"Therefore, O Hari, Brikhbhan's daughter will sulk with you again.\"'","page":493,"meaning_status":"draft"}]},{"type":"verse","number":[977],"number_text":"੯੭੭।","page":493,"lines":[{"gurmukhi":"ਯੌ ਤੁ ਕਹੀ ਉਨ ਹੂੰ ਤੁਮ ਕੋ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਜੁ ਕਹਿਯੋ ਸੁਨ ਲੀਜੈ।","roman":"Yau tu kahee un hoon tum ko brikhbhaan sutaa ju kahiyo sun leejai |","meaning_en":"'So they spoke to you; now hear what Brikhbhan's daughter said:","page":493,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗ ਗਏ ਹਮ ਕੋ ਬ੍ਰਿਜ ਮੈ ਮਨੂਆ ਤੁਮਰੋ ਸੁ ਲਖੋ ਨ ਪ੍ਰਸੀਜੈ।","roman":"Tyaag gae ham ko brij mai manooaa tumro su lakho na praseejai |","meaning_en":"\"You left us in Braj; I see that your heart is not moved.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਬੈਠ ਰਹੇ ਅਬ ਹੋ ਮਥੁਰਾ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਮਨੂਆ ਜਬ ਖੀਜੈ।","roman":"Baith rahe ab ho mathuraa ih bhaati kahiyo manooaa jab kheejai |","meaning_en":"Now you sit in Mathura.\" She said this when her heart was vexed:","page":493,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਹਮ ਕੋ ਤੁਮ ਪੀਠ ਦਈ ਤੁਮ ਕੋ ਤੁਮਰੀ ਮਨ ਭਾਵਤ ਦੀਜੈ। ੯੭੭।","roman":"Jiu ham ko tum peeth daee tum ko tumree man bhaavat deejai | 977 |","meaning_en":"\"As you have turned your back on us, so may you be given what your heart desires.\"'","page":493,"meaning_status":"draft","note":"May be meant ironically, as a reproach; uncertain."}]},{"type":"verse","number":[978],"number_text":"੯੭੮।","page":493,"lines":[{"gurmukhi":"ਅਉਰ ਕਹੀ ਤੁਮ ਸੋ ਬ੍ਰਿਜਨਾਥ ਕਹੀ ਅਬ ਊਧਵ ਸੋ ਸੁਨ ਲਈਯੈ।","roman":"Aur kahee tum so brijnaath kahee ab oodhav so sun laeeyai |","meaning_en":"'And, Lord of Braj, she said something more to you; hear it now from Udhav:","page":493,"meaning_status":"draft"},{"gurmukhi":"ਆਪ ਚਲੋ ਤੁ ਨਹੀ ਕਹਿਯੋ ਨਾਥ ਬੁਲਾਵਨ ਗ੍ਵਾਰਨਿ ਦੂਤ ਪਠਈਯੈ।","roman":"Aap chalo tu nahee kahiyo naath bulaavan gvaarni doot pathaeeyai |","meaning_en":"\"If you will not come yourself, Lord,\" she said, \"send a messenger to call the milkmaids.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਕੋਊ ਦੂਤ ਪਠੋ ਨ ਕਯੋ ਤਬ ਤੋ ਉਠਿ ਆਪਨ ਹੀ ਤਹਿ ਜਈਯੈ।","roman":"Jo ko'oo doot patho na kayo tab to uthi aapan hee tahi jaeeyai |","meaning_en":"If you send no messenger, then rise and go there yourself.","page":493,"meaning_status":"draft"},{"gurmukhi":"ਨਾਤੁਰ ਗ੍ਵਾਰਨਿ ਕੋ ਦ੍ਰਿੜਤਾ ਹੂੰ ਕੋ ਸ੍ਯਾਮ ਕਹੈ ਅਬ ਦਾਨ ਦਿਵਈਯੈ। ੯੭੮।","roman":"Naatur gvaarni ko drirtaa hoon ko syaam kahai ab daan divaeeyai | 978 |","meaning_en":"Otherwise,\" says Shyam, \"now grant the milkmaids the gift of steadfastness.\"'","page":493,"meaning_status":"draft"}]},{"type":"verse","number":[979],"number_text":"੯੭੯।","page":494,"lines":[{"gurmukhi":"ਤੇਰੋ ਹੀ ਧ੍ਯਾਨ ਧਰੈ ਹਰਿ ਜੂ ਅਰੁ ਤੇਰੋ ਹੀ ਲੈ ਕਰਿ ਨਾਮੁ ਪੁਕਾਰੈ।","roman":"Tero hee dhyaan dharai hari joo aru tero hee lai kari naamu pukaarai |","meaning_en":"'Hari, they meditate on you alone and call out, taking your name alone.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਮਾਤ ਪਿਤਾ ਕੀ ਨ ਲਾਜ ਕਰੈ ਹਰਿ ਸਾਇਤ ਸ੍ਯਾਮ ਹੀ ਸ੍ਯਾਮ ਚਿਤਾਰੈ।","roman":"Maat pitaa kee na laaj karai hari saait syaam hee syaam chitaarai |","meaning_en":"They feel no shame before mother and father; every moment they think only of Shyam, Shyam.","page":494,"meaning_status":"draft","note":"ਸਾਇਤ: 'moment' (Arabic sa'at)."},{"gurmukhi":"ਨਾਮ ਅਧਾਰ ਤੇ ਜੀਵਤ ਹੈ ਬਿਨੁ ਨਾਮ ਕਹਿਯੋ ਛਿਨ ਮੈ ਕਸਟਾਰੈ।","roman":"Naam adhaar te jeevat hai binu naam kahiyo chhin mai kastaarai |","meaning_en":"They live by the support of the name; without the name, she said, they suffer in an instant.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਬਿਧਿ ਦੇਖ ਦਸਾ ਉਨ ਕੀ ਅਤਿ ਬੀਚਿ ਬਢਿਯੋ ਜੀਯ ਸੋਕ ਹਮਾਰੈ। ੯੭੯।","roman":"Yaa bidhi dekh dasaa un kee ati beechi badhiyo jeey sok hamaarai | 979 |","meaning_en":"Seeing their condition thus, the grief in my own heart grew very great.'","page":494,"meaning_status":"draft"}]},{"type":"verse","number":[980],"number_text":"੯੮੦।","page":494,"lines":[{"gurmukhi":"ਮਾਤ ਪਿਤਾਨ ਕੀ ਸੰਕ ਕਰੈ ਨਹਿ ਸ੍ਯਾਮ ਹੀ ਸ੍ਯਾਮ ਕਰੈ ਮੁਖ ਸਿਉ।","roman":"Maat pitaan kee sank karai nahi syaam hee syaam karai mukh siu |","meaning_en":"'They have no fear of mother and father; they say only \"Shyam, Shyam\" with their lips.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਭੂਮਿ ਗਿਰੈ ਬਿਧਿ ਜਾ ਮਤਵਾਰ ਪਰੈ ਗਿਰ ਕੈ ਧਰਿ ਪੈ ਸੋਊ ਤਿਉ।","roman":"Bhoomi girai bidhi jaa matvaar parai gir kai dhari pai so'oo tiu |","meaning_en":"They fall to the ground, just as a drunkard falls down on the earth.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਿਜ ਕੁੰਜਨ ਢੂੰਢਤ ਹੈ ਤੁਮ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਧਨ ਲੋਭਕ ਜਿਉ।","roman":"Brij kunjan dhoondhat hai tum ko kabi syaam kahai dhan lobhak jiu |","meaning_en":"They search for you in the groves of Braj, says the poet Shyam, like a miser for wealth.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਤਾ ਤੇ ਕਰੋ ਬਿਨਤੀ ਤੁਮ ਸੋ ਪਿਖ ਕੈ ਤਿਨ ਕੋ ਫੁਨਿ ਹਉ ਦੁਖ ਇਉ। ੯੮੦।","roman":"Ab taa te karo bintee tum so pikh kai tin ko phuni hau dukh iu | 980 |","meaning_en":"So now I plead with you, for having seen them I am pained in this way.'","page":494,"meaning_status":"draft"}]},{"type":"verse","number":[981],"number_text":"੯੮੧।","page":494,"lines":[{"gurmukhi":"ਆਪ ਚਲੋ ਇਹ ਤੇ ਨ ਭਲੀ ਜੁ ਪੈ ਆਪ ਚਲੋ ਨਹੀ ਦੂਤ ਪਠੀਜੈ।","roman":"Aap chalo ih te na bhalee ju pai aap chalo nahee doot patheejai |","meaning_en":"'Go yourself: nothing is better than this; but if you will not go yourself, send a messenger.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਕਰੋ ਬਿਨਤੀ ਤੁਮ ਸੋ ਦੁਹ ਬਾਤਨ ਤੇ ਇਕ ਬਾਤ ਕਰੀਜੈ।","roman":"Taa te karo bintee tum so duh baatan te ik baat kareejai |","meaning_en":"So I plead with you: of these two things, do one.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਜਲ ਕੇ ਬਿਨ ਮੀਨ ਦਸਾ ਸੁ ਦਸਾ ਭਈ ਗ੍ਵਾਰਨਿ ਕੀ ਸੁਨਿ ਲੀਜੈ।","roman":"Jiu jal ke bin meen dasaa su dasaa bhaee gvaarni kee suni leejai |","meaning_en":"As a fish fares without water, so the milkmaids fare; hear it.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਜਲ ਹੋਇ ਉਨੈ ਮਿਲੀਐ ਕਿ ਉਨੈ ਦ੍ਰਿੜਤਾ ਕੋ ਕਹਿਯੋ ਬਰੁ ਦੀਜੈ। ੯੮੧।","roman":"Kai jal hoi unai mileeai ki unai drirtaa ko kahiyo baru deejai | 981 |","meaning_en":"Either become the water and meet them, or, as she said, give them the boon of steadfastness.'","page":494,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"The poet said:","page":494,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":494,"meaning_status":"draft"},{"type":"verse","number":[982],"number_text":"੯੮੨।","page":494,"lines":[{"gurmukhi":"ਬ੍ਰਿਜ ਬਾਸਿਨ ਹਾਲ ਕਿਧੋ ਹਰਿ ਜੂ ਫੁਨਿ ਊਧਵ ਤੇ ਸਭ ਹੀ ਸੁਨ ਲੀਨੋ।","roman":"Brij baasin haal kidho hari joo phuni oodhav te sabh hee sun leeno |","meaning_en":"Hari then heard from Udhav the whole state of the people of Braj,","page":494,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੀ ਕਥਾ ਸੁਨ ਕੈ ਚਿਤ ਤੇ ਸੁ ਹੁਲਾਸ ਘਟੈ ਦੁਖ ਹੋਵਤ ਜੀ ਨੋ।","roman":"Jaa kee kathaa sun kai chit te su hulaas ghatai dukh hovat jee no |","meaning_en":"hearing whose story the heart's joy wanes and the heart is pained.","page":494,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹਿਯੋ ਮੁਖ ਤੇ ਇਹ ਭਾਤਿ ਕਿਧੌ ਕਬਿ ਨੈ ਸੁ ਸੋਊ ਲਖਿ ਲੀਨੋ।","roman":"Syaam kahiyo mukh te ih bhaati kidhau kabi nai su so'oo lakhi leeno |","meaning_en":"Shyam spoke thus with his lips, as the poet has perceived it:","page":494,"meaning_status":"draft"},{"gurmukhi":"ਊਧਵ ਮੈ ਉਨ ਗ੍ਵਾਰਨਿ ਕੋ ਸੁ ਕਹਿਯੋ ਦ੍ਰਿੜਤਾ ਕੋ ਅਬੈ ਬਰੁ ਦੀਨੋ। ੯੮੨।","roman":"Oodhav mai un gvaarni ko su kahiyo drirtaa ko abai baru deeno | 982 |","meaning_en":"'Udhav, I have now granted those milkmaids the boon of steadfastness.'","page":494,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":494,"meaning_status":"draft"},{"type":"verse","number":[983],"number_text":"੯੮੩।","page":494,"lines":[{"gurmukhi":"ਸਤ੍ਰਹ ਸੈ ਚਵਤਾਲ ਮੈ ਸਾਵਨ ਸੁਦਿ ਬਧਵਾਰਿ।","roman":"Satrah sai chavtaal mai saavan sudi badhvaari |","meaning_en":"In (the year) seventeen hundred and forty-four, on a Wednesday of the bright half of Sawan,","page":494,"meaning_status":"draft","note":"Bikrami year 1744 (1687 CE)."},{"gurmukhi":"ਨਗਰ ਪਾਵਟਾ ਮੋ ਤੁਮੋ ਰਚਿਯੋ ਗ੍ਰੰਥ ਸੁਧਾਰਿ। ੯੮੩।","roman":"Nagar paavtaa mo tumo rachiyo granth sudhaari | 983 |","meaning_en":"in the town of Paonta, this book was composed and corrected.","page":494,"meaning_status":"draft","note":"ਤੁਮੋ: printed so; its sense here is unclear."}]},{"type":"verse","number":[984],"number_text":"੯੮੪।","page":494,"lines":[{"gurmukhi":"ਖੜਗ ਪਾਨਿ ਕੀ ਕ੍ਰਿਪਾ ਤੇ ਪੋਥੀ ਰਚੀ ਬਿਚਾਰਿ।","roman":"Kharag paani kee kripaa te pothee rachee bichaari |","meaning_en":"By the grace of the Sword-in-hand, the book was composed with reflection.","page":494,"meaning_status":"draft","note":"ਖੜਗ ਪਾਨਿ: 'He who holds the sword', the Lord."},{"gurmukhi":"ਭੂਲਿ ਹੋਇ ਜਹ ਤਹ ਸੁ ਕਬਿ ਪੜਿਅਹੁ ਸਭੈ ਸੁਧਾਰਿ। ੯੮੪।","roman":"Bhooli hoi jah tah su kabi pariahu sabhai sudhaari | 984 |","meaning_en":"Wherever there is an error, poets, correct it all as you read.","page":494,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਦਸਮ ਸਿਕੰਧੇ ਪੁਰਾਣੇ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਗੋਪੀ ਊਧਵ ਸੰਬਾਦੇ","roman":"Iti sree dasam sikandhe puraane bachitr naatak granthe krisnaavtaare gopee oodhav sanbaade","meaning_en":"Here ends, in the Krishna Avatar of the Bachitra Natak book, (based on) the tenth book of the Purana, in the dialogue of the gopis and Udhav,","page":494,"meaning_status":"draft"},{"gurmukhi":"ਬਿਰਹ ਨਾਟਕ ਬਰਨਨੰ ਨਾਮ ਧਯਾਇ ਸਮਾਪਤਮ ਸਤੁ ਸੁਭਮ ਸਤ।","roman":"Birah naatak barannan naam dhayaai samaaptam satu subham sat |","meaning_en":"the chapter named the description of the drama of separation. All is well and auspicious.","page":494,"meaning_status":"draft"}],"page":494}});
